for xl,yl in pairs(ul)do
wl[xl]=yl
end
wl.nums={}
for zl,Al in pairs(ul.nums or{})do
wl.nums[zl]=Al
end
for Bl,Cl in pairs(vl.nums or{})do
wl.nums[Bl]=Cl
end
if vl.who then
wl.who=vl.who
end
return wl
end
