local Hl={}
for Il,Jl in ipairs(Fl and type(Gl)==Tse[2101]and Gl or{})do
if Jl.playable and not Jl.hand and pb.sure(El,Jl)~=Tse[2464]then
if Jl.family==Tse[2284]and not(bb.reinc and bb.reinc.id and bb.reinc.id~=El)then
bb.reinc={id=El,add=tonumber(Jl.nums and Jl.nums.add)or 0.5,sold=0,ok=true,study=true,studyMax=2}
bb.pasExp={kind=Tse[2284],id=El}
table.insert(Hl,Jl.name..Tse[2473])
else
table.insert(Hl,Jl.name..Tse[2444]..(pb.LOOK[Jl.family]or Tse[2474]))
end
end
end
if#Hl>0 then
F.log(1,Tse[2475],string.format(Tse[2476],V.name(El),table.concat(Hl,Tse[2477])))
end
end
