if#pn.vals<12 then
local qn=math.floor(mn*1000+0.5)/1000
local rn=false
for un,vn in ipairs(pn.vals)do
if vn==qn then
rn=true
break
end
end
if not rn then
table.insert(pn.vals,qn)
