function pb.evidence(Po,Qo,Ro)
local So=type(Ro.nums)==Tse[2101]and Ro.nums or{}
local To=Po.firstPlaced[Qo]
if not To then
return{why=Tse[2499]}
end
local Uo={}
for Vo,Wo in ipairs(Ro.buffs or{})do
Uo[Wo]=true
end
local function Xo(Yo)
if#Yo==0 then
return nil
end
table.sort(Yo)
return Yo[math.ceil(#Yo/2)]
end
if Ro.family==Tse[2284]then
if(Po.sales or 0)==0 then
return{why=Tse[2500]}
end
local Zo,_o
for ap in pairs(Po.own)do
local bp,cp,dp,ep,fp=0,0,0,0,0
for ip,jp in pairs(Po.copies)do
local kp=jp.buff[ap]or 0
if(jp.sold or 0)>0 then
if jp.id~=Qo then
ep=ep+1
end
if kp>0 then
if jp.id==Qo then
bp=bp+1
else
dp=dp+1
end
fp=math.max(fp,kp)
end
elseif kp>0 then
cp=cp+1
end
end
if bp>0 and cp==0 and(not _o or bp>_o)then
Zo,_o={name=ap,other=dp,otherAfter=ep,top=fp},bp
end
end
if not Zo then
return{why=Tse[2501]}
end
local lp=(Zo.other>0 and Tse[1031])or(Zo.otherAfter>0 and Tse[2502])or Tse[2503]
return{seen=true,buff=Zo.name,who=lp,nums={stacks=(Po.sales>1 and Zo.top>1)or nil,sales=Po.sales},why=string.format(Tse[2504],_o,Zo.name,lp==Tse[2502]and Tse[2505]or Tse[1020])}
end
local mp=Ro.trigger and tostring(Ro.trigger):find(Tse[2506],1,true)~=nil
local np=0
for op,pp in ipairs(Po.casts)do
if pp.id==Qo then
np=np+1
end
end
if mp and np==0 and(Ro.family==Tse[2285]or Ro.family==Tse[2282])then
return{why=Tse[2507]}
end
if Ro.family==Tse[2285]then
local qp,rp,vp
for wp,yp in pairs(Po.own)do
if yp.first>=To-1 and(Uo[wp]or yp.first<=To+5 or mp)and(not mp or pb.nearCast(Po,Qo,yp.starts)>0)then
local zp=0
for Ap,Bp in pairs(yp.by)do
if Ap~=Qo then
zp=zp+Bp
end
end
if zp>0 and(not qp or(Uo[wp]and not vp)or((Uo[wp]or false)==(vp or false)and zp>rp))then
qp,rp,vp=wp,zp,Uo[wp]
end
end
end
if not qp then
return{why=Tse[2508]}
