return{seen=true,buff=qp,why=string.format(Tse[2509],qp)}
end
if Ro.family==Tse[2282]then
local Cp,Dp
for Ep,Fp in pairs(Po.foeBuffs)do
if Fp.first>=To-1 and Fp.near>0 and(Uo[Ep]or Fp.near>=0.5*Fp.n)and(not mp or pb.nearCast(Po,Qo,Fp.onsets)>0)then
local Gp=Fp.near+(Uo[Ep]and 1e6 or 0)+(mp and pb.nearCast(Po,Qo,Fp.onsets)*1000 or 0)
if not Dp or Gp>Dp then
Cp,Dp=Ep,Gp
end
end
