if#Hp.durs>=3 then
Ip.secsSeen=math.floor(Xo(Hp.durs)*10+0.5)/10
elseif Hp.foes>=5 then
Ip.keepSeen=true
end
if Hp.spN>=5 then
local Jp=Hp.sp/Hp.spN
if Jp<0.97 then
Ip.slowSeen=math.floor((1-Jp)*100+0.5)/100
end
end
if So.chance and(Po.nearN or 0)>0 then
