nq=pq.to
end
end
if not jq then
local qq,rq,sq
for tq,uq in pairs(Po.copies)do
if uq.id==Qo or(nq and uq.id==nq)then
for vq,wq in pairs(uq.stat or{})do
if wq.hi>wq.lo and(not qq or(wq.hi-wq.lo)>(sq-rq))then
qq,rq,sq=vq,wq.lo,wq.hi
