function pb.model(Kr,Lr,Mr)
local Nr=tostring(Kr)..Tse[2226]..tostring(Mr and Mr.atk)..Tse[2226]..tostring(Mr and Mr.cd)
local Or=pb._model[Nr]
if Or~=nil then
return Or or nil
end
local Pr,Qr={},false
local Rr=math.max(0.3,tonumber(Mr and Mr.cd)or 2)
local Sr=math.min(1,(tonumber(Lr and Lr.n)or 1)/4)
local Tr,Ur=pcall(pb.guess,Kr)
local Vr,Wr={},{}
for Xr,Yr in ipairs(Tr and type(Ur)==Tse[2101]and Ur or{})do
if Yr.hand then
Vr[Yr.pid]=true
end
Wr[Yr.pid]=Yr.nums
end
for Zr,as in pairs(pb.rules(Kr))do
if not Vr[Zr]then
local bs={}
for cs,ds in pairs(type(Wr[Zr])==Tse[2101]and Wr[Zr]or{})do
bs[cs]=ds
end
for es,fs in pairs(type(as.nums)==Tse[2101]and as.nums or{})do
bs[es]=fs
end
local gs=as.trigger~=nil and tostring(as.trigger):find(Tse[2506],1,true)~=nil
if as.family==Tse[2285]then
local hs=(gs and pb.ABILITY_UPTIME or 1)*(as.who==Tse[2354]and pb.RANGE_SHARE or 1)
local js=Pr.aura or{typed={}}
for ks,ls in pairs(type(bs.typed)==Tse[2101]and bs.typed or{})do
js.typed[ks]=math.max(js.typed[ks]or 0,(tonumber(ls)or 0)*hs)
end
local ms=tonumber(bs.dmgMax)or tonumber(bs.dmg)
if ms then
js.dmg=math.max(js.dmg or 0,ms*hs)
end
if bs.crit then
js.crit=math.max(js.crit or 0,(tonumber(bs.crit)or 0)*hs)
end
Pr.aura,Qr=js,true
elseif as.family==Tse[2282]then
local ns=pb.KW[tostring(as.keyword or Tse[1020])]
local ps=tonumber(bs.chance)or 1
local qs=tonumber(bs.secsSeen)or tonumber(bs.secs)or 5
local rs=bs.keep or bs.keepSeen
local ss=rs and math.min(1,ps*4)or math.min(1,qs*ps/Rr)
if gs then
ss=math.min(ss,qs/60)
end
if ns and ns.kind==Tse[2272]and not(type(bs.shred)==Tse[2101])then
local ts=tonumber(bs.amp)
local us=Lr and((type(Lr.ampTypes)==Tse[2101]and Lr.ampTypes[ns.dtype])or(tonumber(Lr.amp)or 0)>0)
if ts and ts>0 and not us then
Pr.fx,Qr=(Pr.fx or 0)+ts*V.TYPED_AMP_SHARE*ss*Sr,true
end
elseif ns and(ns.kind==Tse[2219]or ns.kind==Tse[2280])then
if not(Lr and((tonumber(Lr.stun)or 0)>0 or(tonumber(Lr.slowTime)or 0)>0))then
Pr.stun=(ns.kind==Tse[2280]and 0.5 or 1)*qs
if bs.slow then
Pr.slowP,Pr.slowT=tonumber(bs.slow),qs
end
Qr=true
end
elseif ns and ns.kind==Tse[2221]then
if not(Lr and(tonumber(Lr.slowTime)or 0)>0)then
Pr.slowP,Pr.slowT,Qr=tonumber(bs.slow)or tonumber(bs.slowSeen)or 0.3,qs,true
end
elseif ns and ns.kind==Tse[2279]then
local vs=tonumber(bs.dot)or 0
if vs>0 and(tonumber(Lr and Lr.dot)or 0)<vs*0.5 then
local ws=math.min(1.5,vs)*ps
Pr.dot,Qr=(Pr.dot or 0)+ws,true
if tostring(as.keyword)==Tse[1943]then
Pr.burnDot=(Pr.burnDot or 0)+ws
end
end
end
if type(bs.ampFrom)==Tse[2101]and tostring(bs.ampFrom.kind)==Tse[1943]and(tonumber(bs.ampFrom.amp)or 0)>0 then
local xs=(type(bs.secsBy)==Tse[2101]and#bs.secsBy>0)and bs.secsBy or{tonumber(bs.secsSeen)or tonumber(bs.secs)or 5}
Pr.flames,Qr={amp=tonumber(bs.ampFrom.amp),secs=xs},true
end
elseif as.family==Tse[2340]then
Pr.exec,Qr=tonumber(bs.below)or 0.25,true
end
end
end
pb._model[Nr]=Qr and Pr or false
return Qr and Pr or nil
end
