local eD=mb.charmSlots()
local fD=math.max(1,math.min(eD-2,math.floor(tonumber(O.charmFree)or 2)))
local gD= #dD-(eD-fD)
if gD<=0 then
return{},#dD,eD,fD
end
local hD=mb.charmOn()
local iD={}
for jD,kD in ipairs(dD)do
kD.total=0
for lD,mD in pairs(kD.rolls)do
kD.total=kD.total+mD
if not iD[lD]or mD>(iD[lD].rolls[lD]or 0)then
iD[lD]=kD
end
end
end
local nD={}
for oD,pD in pairs(iD)do
nD[pD]=true
end
local qD={}
for rD,sD in ipairs(dD)do
if not nD[sD]and not sD.worn and sD.uuid~=hD and sD.tier<4 then
table.insert(qD,sD)
end
end
table.sort(qD,function(tD,uD)
if math.abs(tD.total-uD.total)>1e-9 then
return tD.total<uD.total
end
return tD.tier<uD.tier
end)
local vD={}
for wD=1,math.min(gD,#qD)do
table.insert(vD,qD[wD])
