end
function mb.weatherStrength(KD)
local LD=mb.fx(KD)
local MD=LD.dmg/LD.cd/LD.hp/LD.speed*(1+(LD.range-1)/2)
for ND,OD in pairs(LD.kinds)do
MD=MD*(1+bb.rogueShare(ND)*OD)
end
if LD.ice>0 then
local PD=bb.rogueShare(Tse[2235])
MD=MD*(PD+(1-PD)/(1-LD.ice+LD.ice/gb.modFactor(Tse[2641])))
end
if LD.fly>0 then
MD=MD*(1-LD.fly*0.5)
end
if LD.noCC then
MD=MD*0.95
end
if LD.shroud then
MD=MD*0.9
end
if LD.zap then
MD=MD*0.85
end
return MD/mb.weatherK(KD)
end
