local rE=mb.board()
if qE and rE and hE.weather~=Tse[2594]and not rE.weathers[hE.weather]then
jE=jE+(1000+5000*O.pearlValue+50*W.remnantGems(Tse[2592]))/mb.WEATHERS
end
end
