mb.BONUS_BAR,mb.BONUS_SWAPS=1.3,4
function mb.bonusTeam(OE,PE,QE)
if type(OE)~=Tse[2101]or type(PE)~=Tse[2101]or#PE==0 then
return nil
end
local RE,SE=U.now(),N.session()
QE=tonumber(QE)or 12
local TE,UE=pcall(mb.skinPlan)
local VE=TE and type(UE)==Tse[2101]and UE.kinds or{}
local function WE(XE,YE)
local ZE,_E=gb.teamFrom(XE,OE.map),0
for aF,bF in ipairs({1,0.92,1.08})do
if gb.run(OE,ZE,{hpMul=YE*bF}).won then
_E=_E+1
end
task.wait()
if _E>=2 then
return true
end
if aF==2 and _E==0 then
return false
end
end
return false
end
local cF=(WE(PE,mb.BONUS_BAR)and mb.BONUS_BAR)or(WE(PE,1)and 1)or nil
if not cF then
return nil
end
local dF=gb.grownKinds()>=gb.GROWN_MIN
local eF={}
for fF,gF in pairs(SE.profile_data.collection.owned_units)do
local hF=SE.collection:get_unit_by_uuid(gF.uuid)or gF
local iF=(mb.unitDrop(hF,VE))
if iF>0 and N.Units[hF.unit_id]and V.rows(hF.unit_id)and not V.hidden(hF.unit_id)then
local jF,kF=pcall(N.USC.calculate_level,hF.unit_id,tonumber(hF.xp)or 0)
if V.isFarm(hF.unit_id)or not dF or(jF and(tonumber(kF)or 0)>=gb.GROWN_LEVEL)then
local lF,mF=pcall(V.score,hF,OE.mod)
mF=(lF and tonumber(mF)or 0)*V.eventMul(hF,OE.ld)
if not eF[hF.unit_id]or mF>eF[hF.unit_id].sc then
eF[hF.unit_id]={u=hF,d=iF,sc=mF}
end
end
end
end
local nF={}
for oF,pF in pairs(eF)do
table.insert(nF,pF)
end
table.sort(nF,function(qF,rF)
if qF.d~=rF.d then
return qF.d>rF.d
end
return qF.sc>rF.sc
end)
if#nF==0 then
return nil
end
local sF,tF=table.clone(PE),{}
local uF=mb.teamDrop(sF,VE)
local vF=gb.realShares(OE.key,5)
local function wF(xF)
local yF,zF={},0
pcall(gb.run,OE,gb.teamFrom(xF,OE.map),{hpMul=1,dealt=yF})
task.wait()
for AF,BF in pairs(yF)do
zF=zF+(tonumber(BF)or 0)
end
local CF={}
for DF,EF in ipairs(xF)do
CF[EF.unit_id]=tonumber(vF[EF.unit_id])or(((tonumber(yF[V.name(EF.unit_id)])or 0)+(tonumber(yF[Tse[2668]..tostring(EF.unit_id)])or 0))/math.max(1,zF))
end
return CF
end
local FF=wF(sF)
for GF=1,mb.BONUS_SWAPS do
if mb.teamDrop(sF,VE)>=1 or U.now()-RE>QE then
break
end
local HF=false
for IF,JF in ipairs(nF)do
if U.now()-RE>QE then
break
end
local KF=false
for LF,MF in ipairs(sF)do
if MF.uuid==JF.u.uuid or V.sameGroup(MF.unit_id,JF.u.unit_id)then
KF=true
break
end
end
if not KF then
local NF={}
for OF,PF in ipairs(sF)do
if(mb.unitDrop(PF,VE))<JF.d then
table.insert(NF,{i=OF,sc=(tonumber(FF[PF.unit_id])or 0)+((V.isFarm(PF.unit_id)or V.allyBuff(PF.unit_id))and 1e300 or 0)})
end
end
table.sort(NF,function(QF,RF)
return QF.sc<RF.sc
end)
for SF=1,math.min(2,#NF)do
local TF=table.clone(sF)
local UF=TF[NF[SF].i]
TF[NF[SF].i]=JF.u
if mb.teamDrop(TF,VE)>mb.teamDrop(sF,VE)+1e-6 and WE(TF,cF)then
table.insert(tF,string.format(Tse[2669],V.name(JF.u.unit_id),V.name(UF.unit_id)))
sF,HF=TF,true
FF=wF(sF)
break
end
end
end
if HF then
break
end
end
if not HF then
break
end
end
if#tF==0 then
return nil
end
return sF,string.format(Tse[2670],table.concat(tF,Tse[2214]),math.floor(mb.teamDrop(sF,VE)*100+0.5),math.floor(uF*100+0.5),cF)
end
