function mb.skinPlan()
local gG,hG=N.session(),N.prof()
local iG=N.data(Tse[2541])or{}
local jG=(hG.inventory and hG.inventory.unique_items)or hG.unique_items or{}
local kG,lG={},{kinds={},sell={},wear={},pearls=0,missing={}}
for mG,nG in pairs(jG)do
local oG=type(nG)==Tse[2101]and N.Items[nG.item_id]
if oG and oG.item_group==Tse[2541]and oG._skin_set==mb.SKIN_SET and oG.usage and iG[oG.usage.skin_id]then
local pG=kG[nG.item_id]
if not pG then
pG={id=nG.item_id,name=oG.name,rarity=oG.rarity,skinId=oG.usage.skin_id,skin=iG[oG.usage.skin_id],uuids={}}
kG[nG.item_id]=pG
table.insert(lG.kinds,pG)
end
table.insert(pG.uuids,nG.uuid or mG)
end
end
table.sort(lG.kinds,function(qG,rG)
return qG.name<rG.name
end)
local sG=mb.team()
local tG=gG.profile_data.collection.owned_units
for uG,vG in ipairs(lG.kinds)do
for wG,xG in pairs(tG)do
if mb.skinFits(xG.unit_id,vG.skin)then
vG.fits=true
break
end
end
local yG=vG.rarity==Tse[2672]or vG.rarity==Tse[2673]
vG.keep=(vG.fits or yG)and 1 or 0
for zG=vG.keep+1,#vG.uuids do
table.insert(lG.sell,{uuid=vG.uuids[zG],name=vG.name,pearls=mb.SKIN_PRICE[vG.rarity]or 0})
lG.pearls=lG.pearls+(mb.SKIN_PRICE[vG.rarity]or 0)
end
end
for AG,BG in ipairs(sG)do
local CG=BG.skin and BG.skin._skin_id and iG[BG.skin._skin_id]
if not(CG and CG._skin_set==mb.SKIN_SET)then
for EG,FG in pairs(iG)do
if type(FG)==Tse[2101]and FG._skin_set==mb.SKIN_SET and mb.skinFits(BG.unit_id,FG)then
local GG=EG..Tse[2674]
if kG[GG]then
table.insert(lG.wear,{uuid=kG[GG].uuids[1],unit=BG.uuid,unitName=V.name(BG.unit_id),name=kG[GG].name})
else
table.insert(lG.missing,{item=GG,unitName=V.name(BG.unit_id),name=FG.name,boost=tonumber(FG._damage_boost)or 0,drop=mb.SKIN_DROP[FG._skin_rarity]or 0})
end
end
end
end
end
return lG
end
function mb.starPlan(HG)
