function mb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and mb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local qH=N.session()
local function rH(sH,tH,uH)
local vH=F.gameSaid(tH)
ab.pickNote.skins=string.format(Tse[2695],sH,tostring(vH or uH or Tse[2636]))
F.log(1,Tse[2606],ab.pickNote.skins)
F.backoff(Tse[2696],1800)
end
local wH=mb.skinPlan()
if O.skinSmart then
local xH=wH.wear[1]
if xH and(F.req.back.skinWear or 0)<=U.now()then
local yH=kb.slotOf(xH.unit)
if yH then
P.str.reequip={uuid=xH.unit,slot=yH}
F.saveNow()
F.request(Tse[2697],Tse[2698],xH.unit)
local zH=U.now()
while U.now()-zH<4 and kb.slotOf(xH.unit)do
task.wait(0.25)
end
end
local AH=U.now()
local BH,CH=F.request(Tse[2699],Tse[2629],xH.uuid,{unit_uuid=xH.unit})
local function DH()
local EH=qH.collection:get_unit_by_uuid(xH.unit)
return EH and EH.skin~=nil
end
while U.now()-AH<5 and not DH()do
task.wait(0.25)
end
if yH then
kb.reequip()
end
if DH()then
F.log(1,Tse[2606],string.format(Tse[2700],xH.name,xH.unitName))
ab.pickNote.skins=nil
wH=mb.skinPlan()
else
local FH=F.gameSaid(AH)
ab.pickNote.skins=string.format(Tse[2701],xH.name,tostring(FH or CH or Tse[2636]))
F.log(1,Tse[2606],ab.pickNote.skins)
F.backoff(Tse[2699],1800)
end
end
if#wH.sell>0 then
local GH,HH={},0
for IH=1,math.min(50,#wH.sell)do
table.insert(GH,wH.sell[IH].uuid)
HH=HH+wH.sell[IH].pearls
end
local JH=tonumber(N.cur(Tse[2666]))or 0
local KH=U.now()
local LH,MH=F.request(Tse[2702],Tse[2634],GH)
while U.now()-KH<5 and(tonumber(N.cur(Tse[2666]))or 0)<=JH do
task.wait(0.25)
end
local NH=(tonumber(N.cur(Tse[2666]))or 0)-JH
if NH<=0 then
return rH(Tse[2703],KH,MH)
end
cb.add(string.format(Tse[2704],#GH),#GH,Tse[2696],string.format(Tse[2705],U.fmt(NH)))
ab.pickNote.skins=nil
end
end
if O.starOpen then
local OH=qH.inventory
local function PH()
local QH,RH=pcall(OH.get_number_of_owned_item,OH,mb.STAR)
return QH and tonumber(RH)or 0
end
local SH=U.now()
for TH=1,8 do
if U.now()-SH>15 or not F.alive or F.where~=Tse[2173]then
break
end
local UH=PH()
local VH=mb.starPlan(mb.skinPlan())
local WH=U.now()
if UH>0 then
local XH,YH=F.request(Tse[2706],Tse[2707],mb.STAR,{use10=UH>=10,use_all=false})
while U.now()-WH<6 and PH()>=UH do
task.wait(0.25)
end
if PH()>=UH then
return rH(Tse[2708],WH,YH)
end
F.log(1,Tse[2606],string.format(Tse[2709],UH-PH(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
elseif VH.open>0 then
local ZH=VH.open>=10 and 10 or 1
local _H=tonumber(N.cur(Tse[2666]))or 0
local aI,bI=F.request(Tse[2710],Tse[2711],mb.STAR,Tse[2119],Tse[2712],tostring(ZH))
while U.now()-WH<5 and PH()<=0 do
task.wait(0.25)
end
if PH()<=0 then
return rH(Tse[2713],WH,bI)
end
cb.add(string.format(Tse[2714],PH()),_H-(tonumber(N.cur(Tse[2666]))or 0),Tse[2715],Tse[2716]..VH.why)
ab.pickNote.skins=nil
else
break
end
end
end
end
