local Xbb=tonumber(Vbb.story_level_rank)or 6
local Ybb=(Ubb.kind==Tse[2142]and 1.5 or 1)*(Wbb>5 and 2 or 1)
local Zbb=2.1564^(Wbb-1)*(40+10*Xbb)/Ybb
if Ubb.kind==Tse[2121]then
