end
local sdb=kb.nextAct(pdb)
if sdb then
return sdb.text,sdb.kind
end
if O.teamRelics and(tonumber(P.str.noWork.relic)or 0)<=os.time()and(not kdb or not(O.autoTeam and O.play))then
local tdb,udb=kb.relicPlan()
