if ydb==Tse[3166]then
local zdb,Adb=pcall(kb.relicsApply,true)
if not(zdb and Adb)then
P.str.noWork.relic=os.time()+1800
end
else
kb.tick()
end
wdb=wdb+1
task.wait(4)
end
if wdb>0 then
