function kb.tick()
if not O.team then
P.str.next=Tse[3172]
return
end
if P.str.reequip then
kb.reequip()
end
local Bdb
if ab.every(Tse[3173],60)or not P.str.acts then
Bdb=kb.plan()
else
Bdb=kb.acts
end
kb.acts=Bdb or kb.acts or{}
local Cdb=kb.nextAct(kb.acts)
