F.log(1,Tse[2488],Tse[3179]..tostring(Gdb))
end
if kb.workSig()==Edb then
P.str.noWork[Cdb.kind..Tse[2237]..tostring(Cdb.uuid)]=os.time()+1800
end
local Hdb=F.req.back[kb.REMOTE[Cdb.kind]or Tse[1020]]
if Hdb and Hdb>U.now()then
P.str.noWork[Cdb.kind]=os.time()+math.ceil(Hdb-U.now())
