function ab.evolve(Vdb,Wdb)
local Xdb=N.session()
local Ydb=Xdb.collection:get_unit_by_uuid(Vdb.uuid)
if not Ydb then
return false,Tse[3192]
end
local Zdb,_db=0,{}
