end
local neb=string.format(Tse[3196],V.name(Vdb.from),V.name(Vdb.to),U.fmt(Vdb.scoreFrom or 0),U.fmt(Vdb.scoreTo or 0))
cb.add(Tse[3197]..neb,1,Tse[3198],(Wdb or Tse[3199])..(#ieb>0 and(Tse[3200]..table.concat(ieb,Tse[2214]))or Tse[1020]))
F.log(1,Tse[3201],neb..Tse[3202]..(Wdb or Tse[3199])..(#ieb>0 and(Tse[3200]..table.concat(ieb,Tse[2214]))or Tse[1020]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Vdb.to)..Tse[3203]
end
F.log(1,Tse[3201],Tse[3204]..V.name(Vdb.from)..Tse[2791]..tostring(deb)..Tse[3205]..tostring(eeb and eeb.unit_id))
