return nil
end
for Leb,Meb in ipairs(Keb.plans or{})do
if Meb.eventShop and(tonumber(Meb.cost)or 0)>0 and Meb.currency and hb.have(Meb.item)<(tonumber(Meb.need)or 1)and(tonumber(N.cur(Meb.currency))or 0)>=Meb.cost then
