end
if hb.have(Oeb.item)>Qeb then
cb.add(Peb,Oeb.cost,tostring(Oeb.currency),Tse[3214]..V.name(Neb.from)..Tse[3215])
if F.notify then
F.notify(Tse[3211],Tse[3028]..Peb..Tse[3156]..V.name(Neb.from),Tse[3030])
end
pcall(hb.refresh)
return true
end
F.log(1,Tse[3031],string.format(Tse[3216],Peb,tostring(Reb and Seb or Tse[2636])))
F.backoff(Tse[3213],900)
return false
end
function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==Tse[1020]then
return
end
local Ueb=N.session()
if not(Ueb and Ueb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(Tse[3217],Tse[3211],Tse[3218],Tse[3219])
end
local Veb
for Web,Xeb in ipairs(P.goals or{})do
if Xeb.pinned and Xeb.uuid==O.evolveUnit then
Veb=Xeb
break
end
end
if not Veb then
local Yeb=Ueb.collection:get_unit_by_uuid(O.evolveUnit)
local Zeb=N.Units[Yeb.unit_id]
if not(Zeb and Zeb.evolve and Zeb.evolve.evolve_unit)then
ab.pickDone(Tse[3217],Tse[3211],V.name(Yeb.unit_id)..Tse[3220],Tse[3219])
end
return
end
ab.pickNote.autoEvolve=nil
if not Veb.ready and ab.evolveBuy(Veb)then
for _eb,afb in ipairs(P.goals or{})do
if afb.pinned and afb.uuid==O.evolveUnit then
Veb=afb
break
end
end
end
if not Veb.ready then
return
end
local bfb={}
for cfb,dfb in ipairs(V.equipped())do
bfb[dfb.uuid]=true
end
local efb=ab.evoEats(Veb,bfb)
if efb then
ab.pickNote.autoEvolve=efb
return
end
if(ab.evoBlocked[Veb.uuid]or 0)>=os.time()then
return
end
local ffb,gfb=ab.evolve(Veb,Tse[3221])
if ffb then
ab.pickDone(Tse[3217],Tse[3211],gfb)
else
ab.evoBlocked[Veb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=gfb
end
end
