for ifb,jfb in ipairs(P.goals or{})do
if jfb.pinned and jfb.uuid==O.evolveUnit then
return jfb.text..((W.onlyOn()and not jfb.ready)and(Tse[3224]..W.onlyText()..Tse[3225])or Tse[1020])..hfb
end
end
return Tse[3226]..hfb
