ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(kfb)
local lfb=N.session()
local mfb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local nfb={[kfb.uuid]=true,[O.evolveUnit]=true}
for ofb,pfb in ipairs(V.equipped())do
nfb[pfb.uuid]=true
end
for qfb,rfb in ipairs(P.savedTeam or{})do
nfb[rfb]=true
end
for sfb,tfb in ipairs(P.train and P.train.on and P.train.on.base or{})do
nfb[tfb]=true
end
local ufb,vfb={},0
for wfb,xfb in pairs(lfb.profile_data.collection.owned_units)do
local yfb=N.Units[xfb.unit_id]
local zfb=yfb and ab.FUSE_RANK[yfb.rarity]
if zfb and zfb<=mfb and not nfb[wfb]then
local Afb=lfb.collection:get_unit_by_uuid(wfb)or xfb
if not(xfb._locked or Afb._locked)and not(xfb._equipped_relic or Afb._equipped_relic)then
local Bfb,Cfb=pcall(N.USC.calculate_xp_gain_from_fuse,kfb,{Afb},lfb)
Cfb=Bfb and tonumber(Cfb)or 0
if Cfb>0 then
table.insert(ufb,{uuid=wfb,id=xfb.unit_id,xp=Cfb,rarity=yfb.rarity})
vfb=vfb+Cfb
end
end
end
end
table.sort(ufb,function(Dfb,Efb)
if Dfb.xp~=Efb.xp then
return Dfb.xp<Efb.xp
end
return Dfb.uuid<Efb.uuid
end)
local Ffb=math.max(0,kb.xpFor(kfb.unit_id,kb.cap(kfb))-(tonumber(kfb.xp)or 0))
local Gfb,Hfb={},0
for Ifb,Jfb in ipairs(ufb)do
if Hfb>=Ffb then
break
end
table.insert(Gfb,Jfb)
Hfb=Hfb+Jfb.xp
end
return Gfb,Hfb,Ffb,vfb
end
function ab.fuseXpTarget(Kfb)
local Lfb=Kfb and Kfb.collection:get_unit_by_uuid(O.fuseXpUnit)
