function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==Tse[1020]then
return
end
local fgb=N.session()
local ggb=ab.fuseXpTarget(fgb)
if not ggb then
return
end
local hgb=V.name(ggb.unit_id)
local igb,jgb,kgb=ab.xpFodder(ggb)
if kgb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#igb==0 then
ab.pickNote.autoFuseXp=Tse[3236]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=Tse[3237]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local lgb,mgb,ngb=0,0,{}
while F.alive and lgb<10 and not P.pauseAll do
if lgb>0 then
local ogb,pgb,qgb=ab.xpFodder(fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb)
igb,kgb={},qgb
for rgb,sgb in ipairs(ogb)do
if not ngb[sgb.uuid]then
table.insert(igb,sgb)
end
end
if kgb<=0 or#igb==0 then
break
end
end
local tgb={}
for ugb=1,math.min(ab.fuseBatch,#igb)do
table.insert(tgb,igb[ugb].uuid)
end
local vgb=tonumber((fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb).xp)or 0
local wgb=U.now()
local xgb,ygb=F.request(Tse[3238],Tse[3239],O.fuseXpUnit,tgb)
if not xgb and(ygb==Tse[2176]or ygb==Tse[2175])then
if ygb==Tse[2175]or mgb>=3 then
break
end
mgb=mgb+1
task.wait(3.5)
continue
end
while U.now()-wgb<5 and(tonumber((fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb).xp)or 0)<=vgb do
task.wait(0.1)
end
local zgb=tonumber((fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb).xp)or 0
if zgb>vgb then
lgb=lgb+1
for Agb,Bgb in ipairs(tgb)do
ngb[Bgb]=true
end
cb.add(string.format(Tse[3240],#tgb,hgb),#tgb,Tse[3241],string.format(Tse[3242],U.fmt(zgb-vgb)))
F.log(1,Tse[2606],string.format(Tse[3243],#tgb,hgb,U.fmt(zgb-vgb),kb.level(fgb.collection:get_unit_by_uuid(O.fuseXpUnit)or ggb)))
elseif#tgb>20 then
ab.fuseBatch=20
F.log(1,Tse[2606],string.format(Tse[3244],#tgb,tostring(F.gameSaid(wgb)or(xgb and ygb)or Tse[2636])))
else
local Cgb=F.gameSaid(wgb)
ab.pickNote.autoFuseXp=Tse[3245]..tostring(Cgb or(xgb and ygb)or Tse[2636])..Tse[3246]
F.log(1,Tse[2606],Tse[3247]..tostring(Cgb or(xgb and ygb)or Tse[2636]))
F.backoff(Tse[3238],1800)
break
end
end
end
