ab.WORLD_SKIP_RETRY=3600
ab.LOBBY_EVERY=6*3600
function ab.worldSkip()
if F.where~=Tse[2173]or not O.worldSkip or not(O.firstClears or O.onlyStory)then
return
end
local Brb=N.WLO and N.WLO.SKIPPABLE_WORLDS
if type(Brb)~=Tse[2101]then
return
end
local Crb=(N.prof()or{}).level_data or{}
local Drb,Erb,Frb
for Grb,Hrb in ipairs(U.list(N.WLO.WORLD_ORDER))do
local Irb=N.Worlds[Hrb]
if Irb and not Irb.legend_stage and not Irb.raid_world then
local Jrb=U.list(Irb.levels)
local Krb=Jrb[#Jrb]
if Krb and not W.done(Crb,Krb.id,Tse[1025])then
Drb,Erb,Frb=Hrb,Jrb[1],Krb
break
end
end
end
if not(Drb and Brb[Drb]and Erb and Frb)then
return
end
if W.open(Frb.id)or not W.open(Erb.id)then
return
end
P.worldSkip=type(P.worldSkip)==Tse[2101]and P.worldSkip or{}
local Lrb=P.worldSkip[Drb]
if type(Lrb)==Tse[2101]and(Lrb.done or os.time()-(tonumber(Lrb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local Mrb=N.Worlds[Drb]
local Nrb=tostring(Mrb and Mrb.name or Drb)
local Orb={key=Tse[2790]..Frb.id..Tse[2896],kind=Tse[2141],first=true,level=Frb.id,diff=Tse[1025],label=W.levelName(Frb.id)..Tse[2897]}
local Prb,Qrb=pcall(gb.plan,Orb,false)
if not(Prb and type(Qrb)==Tse[2101])then
return
end
if not Qrb.won then
if ab.every(Tse[3492]..Drb,3600)then
F.log(1,Tse[2723],string.format(Tse[3493],Nrb,W.levelName(Frb.id),tostring(Qrb.margin)))
end
return
end
local Rrb={}
for Srb,Trb in ipairs(U.list(Mrb.levels))do
Rrb[Trb.id]=W.done(Crb,Trb.id,Tse[1025])
end
local Urb=U.now()
F.log(1,Tse[2723],string.format(Tse[3494],Nrb,W.levelName(Frb.id),tostring(Qrb.margin)))
local Vrb,Wrb=F.request(Tse[3495],Tse[3496],Drb)
local Xrb=false
while U.now()-Urb<8 do
task.wait(1)
if W.open(Frb.id)then
Xrb=true
break
end
end
local Yrb=F.gameSaid(Urb)
P.worldSkip[Drb]={at=os.time(),done=Xrb or nil,last=Frb.id,said=Yrb and tostring(Yrb):sub(1,80)or nil}
F.saveSoon()
if Xrb then
local Zrb=(N.prof()or{}).level_data or{}
local _rb={}
for asb,bsb in ipairs(U.list(Mrb.levels))do
if bsb.id~=Frb.id and not Rrb[bsb.id]and W.done(Zrb,bsb.id,Tse[1025])then
table.insert(_rb,W.levelName(bsb.id))
end
end
F.log(1,Tse[2723],string.format(Tse[3497],Nrb,#_rb>0 and(Tse[3498]..table.concat(_rb,Tse[2214]))or Tse[3499],Yrb and(Tse[3500]..tostring(Yrb))or Tse[1020]))
W.lastScored=nil
else
F.log(1,Tse[2723],string.format(Tse[3501],Nrb,tostring(Yrb or(Vrb and Wrb)or Tse[2636])))
end
end
function ab.icLaunch(csb)
P.pending={key=csb.key,kind=csb.kind,level=csb.level,diff=csb.diff,label=csb.label,at=os.time(),value=csb.value,room=csb.room}
