if not ysb then
F.log(1,Tse[2488],Tse[3515]..tostring(zsb))
end
P.watch=nil
for Asb,Bsb in pairs(W.PORTALS)do
if(xsb.kind==Tse[2558]and xsb.level==Bsb.level)or(xsb.portalMap and xsb.level==Bsb.from)then
P.watch={key=xsb.key,portal=Asb,item=Bsb.item,have=hb.have(Bsb.item),held= #W.portalsHeld(Asb),used=xsb.kind==Tse[2558],at=os.time()}
end
