if xsb.kind==Tse[2555]and ab.matchOn(xsb)then
P.pending={key=xsb.key,kind=xsb.kind,level=xsb.level,diff=xsb.diff,label=xsb.label,at=os.time(),value=xsb.value}
F.saveNow()
F.log(1,Tse[2723],string.format(Tse[3516],xsb.label,xsb.why or Tse[1020],xsb.score or 0))
ab.matchmake(xsb)
if P.pauseAll then
P.pending=nil
