local Mvb=Jvb.collection:get_unit_by_uuid(Kvb)
local Nvb=Jvb.inventory:get_item_by_uuid(Lvb)
local Ovb=Nvb and Nvb._unique_item_data and Nvb._unique_item_data._unique_relic_data
if Mvb and Ovb and not Mvb._equipped_relic and not Ovb._equipped_unit_uuid and not kb.slotOf(Kvb)then
local Pvb
for Qvb,Rvb in ipairs(V.equipped())do
local Svb=Rvb.u._equipped_relic and Jvb.inventory:get_item_by_uuid(Rvb.u._equipped_relic)
if Svb and Svb.item_id==Nvb.item_id then
Pvb=Rvb
end
end
if Pvb then
P.str.reequip={uuid=Pvb.uuid,slot=Pvb.slot}
F.saveNow()
F.request(Tse[2697],Tse[2698],Pvb.uuid)
local Tvb=U.now()
while U.now()-Tvb<4 and kb.slotOf(Pvb.uuid)do
task.wait(0.25)
end
end
F.request(Tse[3609],Tse[2629],Lvb,{unit_uuid=Kvb})
local Uvb=U.now()
while U.now()-Uvb<3 and Mvb._equipped_relic~=Lvb do
task.wait(0.25)
end
if Pvb then
kb.reequip()
end
F.log(1,Tse[3151],string.format(Tse[3612],V.name(Mvb.unit_id),(N.Items[Nvb.item_id]or{}).name or tostring(Nvb.item_id),Mvb._equipped_relic==Lvb and Tse[1020]or Tse[3613]))
end
P.relicOff[Kvb]=nil
end
