function ab.equipTeam(Vvb,Wvb)
local Xvb={}
for Yvb,Zvb in ipairs(V.equipped())do
Xvb[Zvb.uuid]=true
end
if not P.savedTeam then
local _vb={}
for awb,bwb in ipairs(V.equipped())do
table.insert(_vb,bwb.uuid)
end
P.savedTeam=_vb
end
local cwb,dwb=pcall(ab.relicClash,Vvb)
if not cwb then
F.log(1,Tse[2488],Tse[3614]..tostring(dwb))
end
local ewb={}
for fwb,gwb in ipairs(Vvb)do
ewb[gwb]=true
end
local hwb,iwb=false,{}
for jwb=1,4 do
for kwb in pairs(Xvb)do
if not ewb[kwb]then
local lwb,mwb=F.request(Tse[2697],Tse[2698],kwb)
table.insert(iwb,string.format(Tse[3615],V.name((N.session().collection:get_unit_by_uuid(kwb)or{}).unit_id or Tse[2337]),tostring(mwb)))
task.wait(0.8)
end
end
for nwb,owb in ipairs(Vvb)do
if not Xvb[owb]then
local pwb
if jwb>2 then
local qwb={}
for rwb,swb in ipairs(V.equipped())do
qwb[swb.slot]=true
end
for twb=1,6 do
if not qwb[twb]then
pwb=twb
break
end
end
end
local uwb,vwb
if pwb then
uwb,vwb=F.request(Tse[3149],Tse[3150],owb,pwb)
else
uwb,vwb=F.request(Tse[3149],Tse[3150],owb)
end
table.insert(iwb,string.format(Tse[3616],V.name((N.session().collection:get_unit_by_uuid(owb)or{}).unit_id or Tse[2337]),pwb and(Tse[3617]..pwb)or Tse[1020],tostring(uwb),tostring(vwb)))
task.wait(0.8)
end
end
local wwb=U.now()
while U.now()-wwb<3 and not ib.same(ib.team(),Vvb)do
task.wait(0.25)
end
hwb=ib.same(ib.team(),Vvb)
if hwb then
break
end
Xvb={}
for xwb,ywb in ipairs(V.equipped())do
Xvb[ywb.uuid]=true
end
end
W._sigAt=nil
if hwb then
F.log(1,Tse[3151],Tse[3618].. #Vvb..Tse[3619]..tostring(Wvb))
else
local zwb={}
for Awb,Bwb in ipairs(V.equipped())do
table.insert(zwb,V.name(Bwb.id))
end
F.log(1,Tse[3151],Tse[3620]..tostring(Wvb)..Tse[3621]..table.concat(zwb,Tse[2214])..Tse[3622]..table.concat(iwb,Tse[2477]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local Cwb,Dwb={},{}
for Ewb,Fwb in ipairs(V.equipped())do
Dwb[Fwb.uuid]=true
end
for Gwb,Hwb in ipairs(P.savedTeam or{})do
if not Dwb[Hwb]and N.session().collection:get_unit_by_uuid(Hwb)then
table.insert(Cwb,Hwb)
end
end
local Iwb=0
for Jwb,Kwb in ipairs(Cwb)do
if#V.equipped()>=6 then
break
end
F.request(Tse[3149],Tse[3150],Kwb)
task.wait(0.8)
local Lwb=U.now()
while U.now()-Lwb<3 and#V.equipped()<math.min(6,Iwb+1+(6- #Cwb))do
task.wait(0.25)
end
for Mwb,Nwb in ipairs(V.equipped())do
if Nwb.uuid==Kwb then
Iwb=Iwb+1
end
end
end
local Owb={}
for Pwb,Qwb in ipairs(V.equipped())do
table.insert(Owb,V.name(Qwb.id))
end
F.log(1,Tse[3151],string.format(Tse[3623],Iwb,table.concat(Owb,Tse[2214])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return hwb
end
function ab.ownSwap()
