ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=3600}
function ab.unitEvidence(jxb)
local kxb=P.learn[jxb]
local lxb=kxb and tonumber(kxb.n)or 0
local mxb=db.hive()
local nxb=mxb and type(mxb.units)==Tse[2101]and mxb.units[jxb]
if type(nxb)==Tse[2101]then
lxb=lxb+(tonumber(nxb.matches)or 0)+(tonumber(nxb.matches3)or 0)
end
return lxb
end
function ab.unitLabSafe(oxb)
if O.unitLab==false or type(oxb)~=Tse[2101]or not ab.LAB.KINDS[oxb.kind]or oxb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==Tse[2101]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=Tse[1026]then
return false
end
local pxb,qxb=pcall(ab.matchOn,oxb)
if pxb and qxb then
return false
end
local rxb=type(P.unitLab)==Tse[2101]and P.unitLab or{}
if rxb.pauseKey==oxb.key and os.time()<(tonumber(rxb.pauseUntil)or 0)then
return false
end
local sxb=W.rec(oxb.key)
local txb,uxb=tonumber(sxb.runs)or 0,tonumber(sxb.wins)or 0
if oxb.kind==Tse[2121]then
local vxb,wxb=pcall(W.infDaily,N.prof(),oxb.level,W.infReach(oxb.key))
return txb>=3 and vxb and(tonumber(wxb)or 1)<=0
end
return txb>=5 and(tonumber(sxb.streak)or 0)==0 and uxb/txb>=0.9
end
function ab.unitLab(xxb)
if not ab.unitLabSafe(xxb)then
return
end
P.unitLab=type(P.unitLab)==Tse[2101]and P.unitLab or{}
local yxb=P.unitLab
yxb.tried=type(yxb.tried)==Tse[2101]and yxb.tried or{}
yxb.seen=(tonumber(yxb.seen)or 0)+1
if yxb.seen%ab.LAB.EVERY~=0 then
return
end
local zxb=N.session()
local Axb=V.equipped()
if not zxb or#Axb<2 then
return
end
local Bxb={}
for Cxb,Dxb in ipairs(Axb)do
Bxb[Dxb.uuid]=true
Bxb[Dxb.id]=true
end
local Exb,Fxb,Gxb
for Hxb,Ixb in pairs(zxb.profile_data.collection.owned_units)do
local Jxb=Ixb.unit_id
if not Bxb[Hxb]and not Bxb[Jxb]and N.Units[Jxb]and not V.isFarm(Jxb)and not V.allyBuff(Jxb)and os.time()-(tonumber(yxb.tried[Jxb])or 0)>ab.LAB.AGAIN then
local Kxb=ab.unitEvidence(Jxb)
if Kxb<ab.LAB.MIN_EVIDENCE then
local Lxb=zxb.collection:get_unit_by_uuid(Hxb)or Ixb
local Mxb=kb.score(Lxb)
if Mxb>0 and(not Exb or Kxb<Fxb or(Kxb==Fxb and Mxb>Gxb))then
Exb,Fxb,Gxb={uuid=Hxb,id=Jxb,u=Lxb},Kxb,Mxb
end
end
end
end
if not Exb then
return
end
local Nxb,Oxb
for Pxb,Qxb in ipairs(Axb)do
if not V.isFarm(Qxb.id)and not V.allyBuff(Qxb.id)and Qxb.uuid~=O.evolveUnit then
local Rxb=kb.score(Qxb.u)
if not Nxb or Rxb<Oxb then
Nxb,Oxb=Qxb,Rxb
end
end
end
if not Nxb then
return
end
yxb.tried[Exb.id]=os.time()
local Sxb=0
for Txb in pairs(yxb.tried)do
Sxb=Sxb+1
if Sxb>300 then
yxb.tried[Txb]=nil
end
end
local Uxb,Vxb=gb.levelFor(xxb)
if not Uxb then
return
end
local Wxb=gb.info(Uxb,xxb.key,Vxb,xxb.mod or W.ldMod(Uxb)or W.levelMod(xxb.level))
local Xxb={}
for Yxb,Zxb in ipairs(Axb)do
table.insert(Xxb,Zxb.uuid==Nxb.uuid and Exb.u or Zxb.u)
end
local _xb,ayb=pcall(gb.run,Wxb,gb.teamFrom(Xxb,Wxb.map),{hpMul=1.1})
local byb=_xb and type(ayb)==Tse[2101]and(ayb.won or(Wxb.infinite and(tonumber(ayb.wave)or 0)>=0.8*W.infReach(xxb.key)))
if not byb then
F.log(2,Tse[3633],string.format(Tse[3634],V.name(Exb.id),xxb.label))
return
end
local cyb={}
for dyb,eyb in ipairs(Axb)do
table.insert(cyb,eyb.uuid==Nxb.uuid and Exb.uuid or eyb.uuid)
end
if ab.equipTeam(cyb,Tse[3635]..V.name(Exb.id))then
yxb.now={id=Exb.id,out=Nxb.id,key=xxb.key,at=os.time(),ev=Fxb}
F.log(1,Tse[3633],string.format(Tse[3636],V.name(Exb.id),V.name(Nxb.id),xxb.label,Fxb))
F.saveNow()
end
end
function ab.unitLabDone(fyb)
local gyb=P.unitLab
local hyb=type(gyb)==Tse[2101]and gyb.now
if type(hyb)~=Tse[2101]then
return
end
gyb.now,gyb.restore=nil,true
if bb.key~=hyb.key then
return
end
local iyb=bb.lastEff and bb.lastEff[hyb.id]
gyb.runs=(tonumber(gyb.runs)or 0)+1
gyb.done=type(gyb.done)==Tse[2101]and gyb.done or{}
