gyb.pauseKey,gyb.pauseUntil=hyb.key,os.time()+3600
end
F.log(1,Tse[3633],string.format(Tse[3637],V.name(hyb.id),fyb and Tse[2846]or Tse[3638],iyb and string.format(Tse[3639],iyb)or Tse[3640]))
