end
local oyb=lyb.last and lyb.done and lyb.done[lyb.last]
return string.format(Tse[3642],myb,myb==1 and Tse[1020]or Tse[1947],oyb and string.format(Tse[3643],V.name(lyb.last),oyb.eff and string.format(Tse[3644],oyb.eff)or Tse[3645])or Tse[1020])
end
ab.QUICK_SEARCH=7
function ab.teamFor(pyb,qyb)
if pyb.key==Tse[2821]then
if P.savedTeam then
ab.restoreTeam()
end
return
end
local ryb=N.session()
local syb=P.testTeam
if syb and(syb.left or 0)>0 and syb.key==pyb.key and type(syb.uuids)==Tse[2101]then
local tyb=0
for uyb,vyb in ipairs(syb.uuids)do
if ryb.collection:get_unit_by_uuid(vyb)then
tyb=tyb+1
end
end
if tyb== #syb.uuids then
if P.train.on then
ib.home()
end
if not ib.same(ib.team(),syb.uuids)then
ab.equipTeam(syb.uuids,Tse[3646]..tostring(syb.label))
end
return
end
end
if O.dailyLoop and pyb.kind==Tse[2554]and type(O.dailyTeam)==Tse[2101]and#O.dailyTeam>0 then
local wyb,xyb={},{}
for yyb,zyb in ipairs(P.savedTeam or ib.team())do
local Ayb=ryb.collection:get_unit_by_uuid(zyb)
if Ayb then
xyb[Ayb.unit_id]=zyb
end
end
for Byb,Cyb in ipairs(O.dailyTeam)do
local Dyb,Eyb=xyb[Cyb],nil
if not Dyb then
local Fyb,Gyb=V.isFarm(Cyb),V.rows(Cyb)
for Hyb,Iyb in pairs(ryb.profile_data.collection.owned_units)do
if Iyb.unit_id==Cyb then
local Jyb=ryb.collection:get_unit_by_uuid(Iyb.uuid)or Iyb
local Kyb,Lyb
if Fyb then
Kyb,Lyb=pcall(V.farm,Jyb,Gyb and Gyb.max or 0)
else
Kyb,Lyb=pcall(V.score,Jyb)
end
Lyb=Kyb and Lyb or 0
if not Eyb or Lyb>Eyb then
Dyb,Eyb=Iyb.uuid,Lyb
end
end
end
end
if Dyb then
table.insert(wyb,Dyb)
end
end
if#wyb== #O.dailyTeam then
if P.train.on then
ib.home()
end
if not ib.same(ib.team(),wyb)then
ab.equipTeam(wyb,Tse[3647])
end
return
end
F.log(1,Tse[3151],Tse[3648])
end
local Myb=P.savedTeam or ib.team()
local Nyb={}
for Oyb,Pyb in ipairs(Myb)do
local Qyb=ryb.collection:get_unit_by_uuid(Pyb)
if Qyb then
table.insert(Nyb,Qyb)
end
end
if#Nyb==0 then
return
end
local Ryb=gb.sig(Nyb)
local Syb=P.simTeam[pyb.key]
if not(Syb and Syb.base==Ryb and os.time()-(tonumber(Syb.at)or 0)<120)then
