gb.memoOn()
local Tyb,Uyb=pcall(gb.plan,pyb,true,qyb or(pyb.kind==Tse[2557]and 45)or 20,Nyb)
gb.memo=nil
if not Tyb then
F.log(1,Tse[2488],Tse[3650]..tostring(Uyb))
end
end
local Vyb=P.simTeam[pyb.key]
local Wyb=Vyb and Vyb.base==Ryb and os.time()-(tonumber(Vyb.at)or 0)<120
local Xyb=(Wyb and Vyb.better and type(Vyb.uuids)==Tse[2101]and#Vyb.uuids>0)and Vyb.uuids or Myb
local Yyb=P.train.on
if Yyb and not ib.same(Yyb.base or{},Xyb)then
ib.home()
Yyb=nil
end
if not Yyb and not ib.same(ib.team(),Xyb)then
if Xyb==Myb and P.savedTeam then
