function ab.partyGather()
if ab.partyRole()~=Tse[3652]then
return
end
local Kzb,Lzb=ab.partyHere()
local Mzb=os.time()-(tonumber(P.partyWaitedAt)or 0)>=ab.PARTY_REGROUP_EVERY
local Nzb=Mzb and ab.partyMissing()or{}
if(#Kzb==0 or#Lzb>= #Kzb)and#Nzb==0 then
