F.status(Tse[3169],string.format(Tse[3663],Pzb,math.max(#Kzb- #Lzb,#Nzb)))
if#Nzb>0 then
F.log(1,Tse[3661],string.format(Tse[3664],#Nzb,#Nzb==1 and Tse[3665]or Tse[3666],Pzb,#Nzb==1 and Tse[3667]or Tse[3668]))
