function eb.upgradeGain(BCb,CCb,DCb,ECb,FCb,GCb)
local HCb,ICb=CCb[DCb],CCb[DCb+1]
local JCb=(HCb.cd>0 and HCb.damage/HCb.cd or 0)
local KCb=(ICb.cd>0 and ICb.damage/ICb.cd or 0)*V.aoe(ICb.atk,ICb.range)/math.max(0.3,V.aoe(HCb.atk,HCb.range))
local LCb=JCb>0 and BCb*(KCb/JCb-1)or(GCb or 0)
local MCb=CCb[DCb+2]
if MCb and DCb+1<CCb.max and MCb.cd>0 and ICb.cd>0 and JCb>0 then
local NCb=BCb*((MCb.damage/MCb.cd)/JCb-1)
local OCb=ECb+MCb.cost*FCb
if NCb/OCb>LCb/ECb then
LCb=LCb+(NCb/OCb*ECb-LCb)*0.5
end
end
local PCb=(ICb.range or 0)>(HCb.range or 0)and(1+((ICb.range-HCb.range)/math.max(1,HCb.range)))or 1
return math.max(0,LCb)*PCb
end
function eb.dpsFor(QCb,RCb)
if RCb<=0 then
return 0
end
local SCb={}
for TCb,UCb in ipairs(QCb)do
if not UCb.farm and not UCb.grif and UCb.gain>0 then
table.insert(SCb,UCb)
end
end
table.sort(SCb,function(VCb,WCb)
return VCb.gain/VCb.cost>WCb.gain/WCb.cost
end)
local XCb,YCb=0,0
for ZCb,_Cb in ipairs(SCb)do
if RCb<=0 then
break
end
YCb=_Cb.gain/_Cb.cost
local aDb=math.min(1,RCb/_Cb.cost)
XCb=XCb+_Cb.gain*aDb
RCb=RCb-_Cb.cost*aDb
end
return XCb+math.max(0,RCb)*YCb*0.7
end
function eb.shieldDps(bDb,cDb,dDb,eDb,fDb,gDb,hDb)
if(eDb or 0)<=0 or(bDb or 0)<=0 or(fDb or 0)<=0 then
return bDb or 0
end
cDb,dDb,gDb=math.max(0.3,cDb or 2),math.max(1,dDb or 1),gDb or 1
local iDb=bDb*gDb*cDb/dDb
return fDb*dDb/((eDb/math.max(1,hDb or 1)+math.max(1,fDb/iDb))*cDb)/gDb
end
function eb.shieldGain(jDb,kDb,lDb,mDb,nDb,oDb,pDb,qDb)
local rDb,sDb=V.attackInfo(kDb.atk,kDb.range),V.attackInfo(mDb.atk,mDb.range)
local tDb=eb.shieldDps(jDb,(tonumber(kDb.cd)or 2)*(pDb or 1),rDb.n,nDb,oDb,qDb,rDb.hits)
local uDb=eb.shieldDps(lDb,(tonumber(mDb.cd)or 2)*(pDb or 1),sDb.n,nDb,oDb,qDb,sDb.hits)
local vDb=math.max(0,((tonumber(mDb.range)or 0)-(tonumber(kDb.range)or 0))/math.max(1,tonumber(kDb.range)or 1))
return math.max(0,uDb-tDb)+tDb*vDb
end
function eb.shieldWork(wDb,xDb,yDb,zDb,ADb,BDb,CDb,DDb,EDb)
if(zDb or 0)<=0 then
return 0
end
local FDb=3*zDb*(ADb or 1)/math.max(1,BDb or 20)
if(yDb or 0)>=FDb then
return 0
end
return math.max(1,wDb or 1)*math.max(1,EDb or 1)/math.max(0.3,xDb or 2)*math.min(CDb or 0,DDb or 0)
end
function eb.holdGain(GDb,HDb,IDb,JDb)
if not GDb or(HDb or 0)<=0 then
return 0
end
local KDb,LDb=tonumber(GDb.stun)or 0,tonumber(GDb.slowTime)or 0
if KDb<=0 and LDb<=0 then
return 0
end
local MDb,NDb=KDb>0 and KDb or LDb,KDb>0 and 1 or(tonumber(GDb.slowPct)or 0.3)
