end
local KRb,LRb=0,{}
for MRb,NRb in pairs(P.simCal or{})do
for ORb,PRb in ipairs({Tse[3821],Tse[3822]})do
for QRb,RRb in pairs(type(NRb)==Tse[2101]and type(NRb[PRb])==Tse[2101]and NRb[PRb]or{})do
