KRb=KRb+1
LRb[QRb]=true
end
end
end
end
P.footV=2
if KRb>0 then
local TRb={}
for URb in pairs(LRb)do
table.insert(TRb,string.format(Tse[3823],V.name(URb),V.DRONES[URb].moveK))
end
F.log(1,Tse[2212],string.format(Tse[3824],table.concat(TRb,Tse[2214]),KRb))
end
F.saveSoon()
