function gb.footMove1()
local VRb={}
local function WRb(XRb)
if VRb[XRb]==nil then
local YRb,ZRb=0,0
local _Rb=P.learn[XRb]
if _Rb and tonumber(_Rb.n)and _Rb.n>=1 then
local aSb=tonumber(_Rb.eff)or 1
if(tonumber(_Rb.v)or 0)<3 then
aSb=aSb*V.effRescale(XRb)
end
if(tonumber(_Rb.v)or 0)<4 then
