if bSb then
YRb,ZRb=YRb+math.log(math.max(0.01,bSb))*cSb,ZRb+cSb
end
VRb[XRb]=V.nudgeFrom(YRb,ZRb)
end
return VRb[XRb]
end
local dSb=0
for eSb,fSb in pairs(P.simCal or{})do
for gSb,hSb in ipairs({Tse[3821],Tse[3822]})do
for iSb,jSb in pairs(type(fSb)==Tse[2101]and type(fSb[hSb])==Tse[2101]and fSb[hSb]or{})do
if type(jSb)==Tse[2101]and tonumber(jSb.k)and not tonumber(jSb.nu)then
jSb.nu=WRb(iSb)
dSb=dSb+1
end
end
end
end
for kSb in pairs(P.learn or{})do
WRb(kSb)
end
for lSb,mSb in pairs(P.learn or{})do
