local qSb=V.nudge(oSb)
if math.abs(qSb/pSb-1)>=0.05 then
table.insert(nSb,{d=math.abs(math.log(qSb/pSb)),t=string.format(Tse[3825],V.name(oSb),pSb,qSb)})
