end)
local tSb={}
for uSb,vSb in ipairs(nSb)do
if uSb<=8 then
table.insert(tSb,vSb.t)
end
end
F.log(1,Tse[2212],string.format(Tse[3826],#tSb>0 and(Tse[2444]..table.concat(tSb,Tse[2477]))or Tse[1020],dSb))
F.saveSoon()
