function jb.payValue()
local Ejc,Fjc=0,0
for Gjc,Hjc in ipairs(P.dg.pay or{})do
if type(Hjc.items)==Tse[2101]then
local Ijc=tonumber(Hjc.gems)or 0
for Jjc,Kjc in pairs(Hjc.items)do
if(tonumber(Kjc)or 0)>0 then
Ijc=Ijc+W.itemValue(Jjc,Kjc)
end
end
Ejc,Fjc=Ejc+Ijc,Fjc+1
end
end
if Fjc<5 then
return nil
end
return Ejc/Fjc*0.7
