local Ljc=type(P.dg)==Tse[2101]and type(P.dg.lossCalls)==Tse[2101]and P.dg.lossCalls or{}
return U.clamp(((tonumber(Ljc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(Ljc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(Mjc)
local Njc,Ojc=jb.curses(Mjc),jb.lives(Mjc)
local Pjc=jb.res(Mjc)
local Qjc=jb.rooms(Mjc)
local Rjc={}
for Sjc,Tjc in ipairs(Qjc)do
table.insert(Rjc,tostring(Tjc.r._r))
end
local Ujc=table.concat(Rjc,Tse[2965])..string.format(Tse[4035],Ojc,Pjc,Njc,W.teamSig())
if jb._pick and jb._pick.sig==Ujc then
return jb._pick.x
end
local Vjc,Wjc,Xjc,Yjc
for Zjc,_jc in ipairs(Qjc)do
local akc=jb.roomValue(_jc,Pjc)
local bkc,ckc
for dkc,ekc in ipairs(jb.after(Mjc,_jc.choice))do
local fkc=jb.roomValue(ekc,Pjc)
if not bkc or fkc>bkc then
bkc,ckc=fkc,ekc
end
end
local gkc,hkc=jb.winP(_jc)
local ikc=hkc~=nil and hkc.won==false
local jkc=Ojc>=3 and 1 or(Ojc==2 and 2 or 6)
local kkc=1-(1-gkc)^math.max(1,Ojc)
_jc.oldScore=kkc*(akc+0.6*(bkc or 0))-(1-gkc)*jkc
if ikc then
gkc=math.min(gkc,jb.lossWin())
kkc=gkc
jkc=jkc*2
end
_jc.p,_jc.sim,_jc.value,_jc.nextValue,_jc.nextRoom,_jc.simLost=gkc,hkc,akc,bkc or 0,ckc,ikc or nil
_jc.score=kkc*(akc+0.6*(bkc or 0))-(1-gkc)*jkc
local lkc,mkc,nkc=pcall(jb.curseGate,_jc,Mjc)
if lkc and not mkc then
_jc.blocked=nkc
end
if not _jc.blocked then
if not Vjc or _jc.score>Vjc.score then
Vjc=_jc
end
if ikc then
if not Yjc or _jc.score>Yjc.score then
Yjc=_jc
end
elseif not Xjc or _jc.score>Xjc.score then
Xjc=_jc
end
end
if not Wjc or _jc.score>Wjc.score then
Wjc=_jc
end
end
if Vjc and Vjc.simLost and Xjc then
F.log(1,Tse[4036],string.format(Tse[4037],jb.roomName(Vjc),tostring(Vjc.sim and Vjc.sim.margin or Tse[2337]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Xjc)))
elseif Vjc and Yjc and Yjc~=Vjc and Yjc.oldScore>Vjc.score then
F.log(1,Tse[4036],string.format(Tse[4038],jb.roomName(Yjc),tostring(Yjc.sim and Yjc.sim.margin or Tse[2337]),jb.roomName(Vjc)))
end
Vjc=Vjc or Wjc
jb._pick={sig=Ujc,x=Vjc,rooms=Qjc}
return Vjc
end
