jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(ilc,jlc)
local klc=jb.cleared(ilc)
local llc=jb.res(ilc)
local mlc=1+0.1*(jb.items(ilc)._curse_shop or 0)
local nlc=jb.shopAhead(ilc)and math.ceil(jb.LUCK_RESERVE*mlc)or 0
local olc={}
local plc,qlc={},0
for rlc,slc in ipairs(jb.offers(jlc and jlc.data))do
slc.cost=math.ceil(slc.cost*mlc)
table.insert(plc,tostring(jb.item(slc.id).name or slc.id))
if not slc.bought and not jb.isCurse(slc.id)then
slc.luck=tonumber(jb.item(slc.id).luck_increase)~=nil
slc.v=jb.itemValue(slc.id,ilc)
if not slc.luck and slc.v/math.max(1,slc.cost)<jb.MIN_WORTH then
qlc=qlc+1
elseif slc.v>0 and(slc.luck or klc>=10 or slc.v/math.max(1,slc.cost)>=jb.TOP_WORTH)then
table.insert(olc,slc)
end
end
end
table.sort(olc,function(tlc,ulc)
if tlc.luck~=ulc.luck then
return tlc.luck
end
return tlc.v/math.max(1,tlc.cost)>ulc.v/math.max(1,ulc.cost)
end)
local vlc,wlc,xlc={},0,0
for ylc,zlc in ipairs(olc)do
if zlc.cost<=llc-(zlc.luck and 0 or nlc)then
if jb.buy(zlc)then
llc=jb.res(jb.data())
table.insert(vlc,string.format(Tse[4049],tostring(jb.item(zlc.id).name or zlc.id),zlc.cost))
end
elseif zlc.cost<=llc then
xlc=xlc+1
else
wlc=wlc+1
end
end
jb.note(string.format(Tse[4050],klc,#plc>0 and table.concat(plc,Tse[2214])or Tse[4051],#vlc>0 and(Tse[4052]..table.concat(vlc,Tse[2214]))or(klc<10 and Tse[4053]or(xlc>0 and Tse[4054]or Tse[4055])),llc,wlc>0 and string.format(Tse[4056],wlc)or Tse[1020],xlc>0 and string.format(Tse[4057],xlc,nlc)or Tse[1020],qlc>0 and string.format(Tse[4058],qlc)or Tse[1020]))
F.request(Tse[4059],Tse[4060])
