function jb.openChests(bmc,cmc)
local dmc,emc,fmc=jb.res(bmc)
local gmc=jb.lives(bmc)
local hmc=jb.cleared(bmc)
if not(cmc or hmc>=jb.ROOMS or gmc<=1)then
jb.note(string.format(Tse[4073],hmc,emc,fmc,jb.luck(bmc)))
F.request(Tse[4059],Tse[4060])
return
end
local imc,jmc,kmc=0,0,0
local lmc=tonumber(N.cur(Tse[2166]))or 0
local mmc=jb.wallet()
for nmc=1,emc+fmc+4 do
local omc,pmc,qmc=jb.res(jb.data())
if pmc+qmc<=0 or kmc>=2 then
break
end
local rmc,smc
if pmc>0 then
rmc,smc=F.request(Tse[4074],Tse[4075])
else
rmc,smc=F.request(Tse[4074],Tse[4075],true)
end
if rmc and smc~=nil then
F.log(1,Tse[4036],Tse[4076]..(type(smc)==Tse[2101]and U.json(U.plain(smc)):sub(1,300)or tostring(smc)))
end
local tmc=U.now()
while U.now()-tmc<4 do
local umc,vmc,wmc=jb.res(jb.data())
if vmc<pmc or wmc<qmc then
break
end
task.wait(0.25)
end
local xmc,ymc,zmc=jb.res(jb.data())
if ymc<pmc then
imc=imc+(pmc-ymc)
kmc=0
elseif zmc<qmc then
jmc=jmc+(qmc-zmc)
kmc=0
else
kmc=kmc+1
end
task.wait(1)
if ymc<pmc or zmc<qmc then
local Amc=jb.wallet()
local Bmc=jb.walletDiff(mmc,Amc)
F.log(1,Tse[4036],(zmc<qmc and Tse[4077]or Tse[4076])..Bmc)
P.dg.pay=P.dg.pay or{}
local Cmc={}
for Dmc,Emc in pairs(Amc.items)do
if Emc~=(mmc.items[Dmc]or 0)then
Cmc[Dmc]=Emc-(mmc.items[Dmc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=zmc<qmc,gems=Amc.gems-mmc.gems,luck=jb.luck(bmc),paid=Bmc,items=Cmc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
mmc=Amc
end
end
jb.note(string.format(Tse[4078],imc,jmc,cmc and Tse[4079]or(gmc<=1 and Tse[4080]or Tse[4081]),jb.luck(bmc),(tonumber(N.cur(Tse[2166]))or 0)-lmc))
local Fmc,Gmc,Hmc=jb.res(jb.data())
if(cmc or hmc>=jb.ROOMS)and Gmc+Hmc>0 then
jb.note(string.format(Tse[4082],Gmc,Hmc))
W.rec(Tse[2821]).restUntil=os.time()+1800
return Tse[4083]
end
if not cmc then
F.request(Tse[4059],Tse[4060])
end
end
function jb.act(Imc)
