end
end
if#enc==0 then
return
end
local mnc=jb.mod(Zmc.r._l)
local nnc=gb.applyFx(gb.info(gb.slim(Zmc.r._l),Tse[2821],nil,mnc),dnc)
local onc=jb.applyK(nnc,Zmc.r._r)
if onc>1 then
F.log(1,Tse[3788],string.format(Tse[4098],Zmc.d,onc))
end
F.status(Tse[3169],Tse[4099]..Zmc.d)
gb.memoOn()
local pnc=jb.ways(nnc)
local qnc=type(P.dg.styles)==Tse[2101]and P.dg.styles[tostring(Zmc.r._r)]or nil
local function rnc(snc,tnc)
local unc=gb.sig(snc)
local vnc=type(P.dg.teams)==Tse[2101]and P.dg.teams[unc]or{}
local wnc=type(P.dg.lost)==Tse[2101]and P.dg.lost[tostring(Zmc.r._r)]and P.dg.lost[tostring(Zmc.r._r)][unc]or 0
local xnc=type(P.dg.bailed)==Tse[2101]and type(P.dg.bailed[tostring(Zmc.r._r)])==Tse[2101]and tonumber(P.dg.bailed[tostring(Zmc.r._r)][unc])or 0
wnc=wnc+xnc
local ync,znc,Anc,Bnc=gb.strength(tnc.info,snc)
local Cnc=math.clamp((tonumber(vnc.w)or 0)-2*(tonumber(vnc.l)or 0),-6,3)
if Zmc.d>=13 then
Cnc=math.min(Cnc,1)
end
Cnc=Cnc-3*wnc
local Dnc=qnc and type(qnc.lost)==Tse[2101]and qnc.lost[tnc.style]or nil
if type(Dnc)==Tse[2101]and Dnc.sig==unc then
Cnc=Cnc-3
end
return{score=ync+Cnc,wins=ync,atOne=znc,reach=Anc,far=Bnc,lostHere=wnc,left=xnc,w=tonumber(vnc.w)or 0,l=tonumber(vnc.l)or 0,style=tnc.style}
end
local function Enc(Fnc)
for Gnc,Hnc in ipairs(pnc)do
if Hnc.style==Fnc then
return Hnc
end
end
return pnc[2]
end
local function Inc(Jnc,Knc)
return not Knc or Jnc.score>Knc.score or(Jnc.score==Knc.score and(Jnc.far or 0)>(Knc.far or 0))
end
local function Lnc(Mnc)
local Nnc
for Onc,Pnc in ipairs(pnc)do
local Qnc=rnc(Mnc,Pnc)
if Inc(Qnc,Nnc)then
Nnc=Qnc
end
task.wait()
end
return Nnc
end
local Rnc=Lnc(enc)
if Rnc.wins>=3* #gb.LADDER and Rnc.lostHere==0 then
gb.memo=nil
local Snc,Tnc={},{}
for Unc,Vnc in ipairs(enc)do
table.insert(Snc,Vnc.uuid)
table.insert(Tnc,V.name(Vnc.unit_id))
end
P.simTeam.dg={uuids=Snc,names=Tnc,won=true,wave=nnc.total,better=false,cur={won=true,wave=nnc.total},at=os.time(),label=Tse[4100],seed=tostring(Zmc.r._r),style=Rnc.style}
F.log(1,Tse[3788],string.format(Tse[4101],Zmc.d,gb.LADDER[#gb.LADDER],Rnc.w,Rnc.l))
pcall(function()
local Wnc,Xnc=pcall(jb.roomName,Zmc)
gb.explainSave(Tse[2821],string.format(Tse[4102],Zmc.d,Wnc and tostring(Xnc)or Tse[2337]),nnc,enc,{string.format(Tse[4103],gb.LADDER[#gb.LADDER],Rnc.w,Rnc.l)},false,enc,{won=true,wave=nnc.total,total=nnc.total,steps=Rnc.wins,mySteps=Rnc.wins,realW=Rnc.w,realL=Rnc.l})
end)
if anc and type(P.savedTeam)==Tse[2101]and not ib.same(ib.team(),P.savedTeam)then
jb.startTeam(P.savedTeam,Zmc,Tse[4104]..Zmc.d,true)
end
return
end
local Ync=gb.pool(mnc,nnc)
local Znc=(jb.lives(_mc)<=1 and 45 or 20)/ #pnc
local _nc,aoc,boc,coc
for doc,eoc in ipairs(pnc)do
local foc,goc,hoc,ioc=gb.bestTeam(eoc.info,enc,Ync,Znc)
local joc=rnc(foc,eoc)
if Inc(joc,coc)then
_nc,aoc,boc,coc=foc,goc,ioc,joc
end
end
local koc=gb.sig(_nc)==gb.sig(enc)
if koc then
coc=Rnc
end
if(nnc.regen or 0)>0 then
local loc=false
for moc,noc in ipairs(enc)do
if V.bleeds(noc.unit_id)then
loc=true
end
end
for ooc,poc in ipairs(_nc)do
if V.bleeds(poc.unit_id)then
loc=true
end
end
local qoc=not loc and V.bestBleeder(enc)or nil
if qoc then
local roc={}
for soc,toc in ipairs(enc)do
if not V.isFarm(toc.unit_id)and not V.allyBuff(toc.unit_id)then
local uoc=table.clone(enc)
uoc[soc]=qoc
local voc=rnc(uoc,Enc(coc.style))
table.insert(roc,string.format(Tse[4105],V.name(toc.unit_id),voc.wins))
if voc.score>coc.score then
_nc,coc,koc=uoc,voc,false
aoc={won=voc.wins>0,wave=voc.reach}
end
task.wait()
end
end
F.log(1,Tse[3788],string.format(Tse[4106],Zmc.d,V.name(qoc.unit_id),V.bleeds(qoc.unit_id)or 0,table.concat(roc,Tse[2477])))
jb.bleedTried=string.format(Tse[4107],V.name(qoc.unit_id),V.bleeds(qoc.unit_id)or 0,table.concat(roc,Tse[2477]))
end
end
gb.memo=nil
local woc=coc.wins>Rnc.wins or(coc.wins==Rnc.wins and(coc.far or 0)>(Rnc.far or 0))
local xoc=not koc and woc and coc.lostHere<=Rnc.lostHere
local yoc,zoc={},{}
for Aoc,Boc in ipairs(_nc)do
table.insert(yoc,Boc.uuid)
table.insert(zoc,V.name(Boc.unit_id))
end
P.simTeam.dg={uuids=yoc,names=zoc,won=aoc.won,wave=aoc.wave,better=xoc,cur={won=boc.won,wave=boc.wave},at=os.time(),label=Tse[4100],seed=tostring(Zmc.r._r),style=(xoc and coc.style)or Rnc.style}
local function Coc(Doc)
return string.format(Tse[4108],Doc.wins,jb.WAY_WORDS[Doc.style]or Tse[1020],math.floor(Doc.reach+0.5),Doc.w,Doc.l)
end
pcall(function()
local Eoc={string.format(Tse[4109],#Ync)}
if jb.bleedTried then
table.insert(Eoc,jb.bleedTried)
end
jb.bleedTried=nil
local function Foc(Goc)
return string.format(Tse[4110],Goc.wins,3* #gb.LADDER,jb.WAY_WORDS[Goc.style]or Tse[1020],Goc.w,Goc.l,(Goc.lostHere or 0)>0 and string.format(Tse[4111],Goc.lostHere,(Goc.left or 0)>0 and string.format(Tse[4112],Goc.left)or Tse[1020])or Tse[1020])
end
if koc and Rnc.wins>=3* #gb.LADDER then
table.insert(Eoc,string.format(Tse[4113],gb.LADDER[#gb.LADDER],Rnc.w,Rnc.l))
elseif koc then
table.insert(Eoc,Tse[4114]..Foc(Rnc))
else
table.insert(Eoc,Tse[4115]..Foc(coc))
table.insert(Eoc,Tse[4116]..Foc(Rnc))
if xoc then
table.insert(Eoc,Tse[4117])
elseif not woc then
table.insert(Eoc,Tse[4118])
else
table.insert(Eoc,string.format(Tse[4119],coc.lostHere))
end
end
local Hoc,Ioc=pcall(jb.roomName,Zmc)
local Joc=xoc and coc or Rnc
gb.explainSave(Tse[2821],string.format(Tse[4102],Zmc.d,Hoc and tostring(Ioc)or Tse[2337]),nnc,xoc and _nc or enc,Eoc,xoc,enc,{won=xoc and aoc.won or boc.won,wave=xoc and aoc.wave or boc.wave,total=nnc.total,steps=Joc.wins,mySteps=Rnc.wins,realW=Joc.w,realL=Joc.l})
end)
if not xoc then
if koc and Rnc.wins>=3* #gb.LADDER then
F.log(1,Tse[3788],string.format(Tse[4120],Zmc.d,#Ync,gb.LADDER[#gb.LADDER],Rnc.w,Rnc.l))
elseif koc then
F.log(1,Tse[3788],string.format(Tse[4121],Zmc.d,#Ync,Coc(Rnc)))
elseif not woc then
F.log(1,Tse[3788],string.format(Tse[4122],Zmc.d,Coc(Rnc),table.concat(zoc,Tse[2214]),Coc(coc)))
else
F.log(1,Tse[3788],string.format(Tse[4123],Zmc.d,Coc(Rnc),table.concat(zoc,Tse[2214]),coc.lostHere,Coc(coc)))
end
if anc and type(P.savedTeam)==Tse[2101]and not ib.same(ib.team(),P.savedTeam)then
jb.startTeam(P.savedTeam,Zmc,Tse[4104]..Zmc.d,true)
end
return
end
F.log(1,Tse[3788],string.format(Tse[4124],Zmc.d,table.concat(zoc,Tse[2214]),Coc(coc),Coc(Rnc)))
if anc then
if not ib.same(ib.team(),yoc)then
jb.startTeam(yoc,Zmc,Tse[4125]..Zmc.d)
end
return
end
if O.autoTeam then
ab.equipTeam(yoc,Tse[4125]..Zmc.d)
task.wait(0.5)
else
F.log(1,Tse[3788],Tse[4126])
end
end
function jb.enter(Koc,Loc,Moc)
for Noc=1,5 do
local Ooc,Poc=pcall(jb.act,Koc)
if not Ooc then
F.log(1,Tse[2488],Tse[4127]..tostring(Poc))
break
end
if Poc==Tse[4083]then
return false
end
if not Poc then
break
end
task.wait(2)
Koc=jb.data()
if not(Koc and Koc._started)then
return false
end
end
jb._pick=nil
local Qoc=jb.pick(Koc)
if not Qoc then
jb.logState(Koc,Tse[4128])
local Roc,Soc,Toc=jb.res(Koc)
if Soc+Toc>0 then
F.log(1,Tse[4036],string.format(Tse[4129],Soc,Toc))
W.rec(Tse[2821]).restUntil=os.time()+1800
return false
end
F.log(1,Tse[4036],Tse[4130])
F.request(Tse[4059],Tse[4060])
return false
end
local Uoc,Voc=pcall(jb.planTeam,Qoc,Koc,Moc)
if not Uoc then
F.log(1,Tse[2488],Tse[4131]..tostring(Voc))
end
if not Moc then
local Woc=P.simTeam.dg
local Xoc=tostring(Qoc.r._r)
P.dg.swapFail=type(P.dg.swapFail)==Tse[2101]and P.dg.swapFail or{}
local Yoc=tonumber(P.dg.swapFail[Xoc])or 0
local Zoc=jb.forced(Qoc)
local _oc=(Zoc and Zoc.uuids)or((Woc and Woc.better and Woc.seed==Xoc and Yoc<2)and Woc.uuids)or P.savedTeam
local apc=ib.team()
local bpc= #apc==6 and(not _oc or ib.same(apc,_oc))
if not bpc then
P.dg.swapFail[Xoc]=Yoc+1
local cpc={}
for dpc,epc in ipairs(V.equipped())do
table.insert(cpc,V.name(epc.id))
end
if Yoc+1>=2 and Woc and Woc.better and Woc.seed==Xoc then
Woc.better=false
F.log(1,Tse[3151],string.format(Tse[4132],Qoc.d))
pcall(ab.restoreTeam)
end
F.log(1,Tse[4036],string.format(Tse[4133],Qoc.d,#apc,table.concat(cpc,Tse[2214])))
F.status(Tse[3169],Tse[4134]..Qoc.d)
W.rec(Tse[2821]).restUntil=os.time()+45
P.pending=nil
F.saveSoon()
return false
end
P.dg.swapFail[Xoc]=nil
local fpc,gpc=pcall(kb.relicsApply)
if not fpc then
F.log(1,Tse[2488],Tse[3515]..tostring(gpc))
end
end
if jb.lives(Koc)<=1 then
P.dg.lost=P.dg.lost or{}
local hpc=jb.sim(Qoc)
local ipc=(P.dg.lost[tostring(Qoc.r._r)]or{})[W.teamSig()]or 0
local jpc= #V.equipped()<6
if(not hpc or ipc>=2 or jpc)and not(jb.playLast()and not jpc)then
local kpc=jpc and string.format(Tse[4135],#V.equipped())or ipc>=2 and string.format(Tse[4136],ipc)or Tse[4137]
jb.note(string.format(Tse[4138],Qoc.d,kpc))
W.rec(Tse[2821]).restUntil=os.time()+3600
P.pending=nil
F.saveSoon()
return false
end
end
P.dg.room={seed=Qoc.r._r,d=Qoc.d}
P.pending={key=Tse[2821],kind=Tse[2122],level=Tse[2122],diff=Tse[2546],label=Tse[4139]..Qoc.d,at=os.time(),value=Loc,depth=Qoc.d}
if P.nextMode==Tse[2821]then
P.nextMode=nil
end
local lpc,mpc,npc=jb.res(Koc)
local opc=string.format(Tse[4140],math.floor(Qoc.p*100+0.5),Qoc.sim and(Tse[4141]..tostring(Qoc.sim.margin)..Tse[2763])or Tse[1020],Qoc.nextRoom and jb.roomName(Qoc.nextRoom)or Tse[4142],jb.lives(Koc),lpc,mpc,npc)
F.log(1,Tse[2723],string.format(Tse[4143],Qoc.d,jb.ROOMS,Moc and Tse[4144]or Tse[1020],jb.roomName(Qoc),opc))
local ppc={}
for qpc,rpc in ipairs(jb._pick and jb._pick.rooms or{})do
if rpc~=Qoc then
table.insert(ppc,string.format(Tse[4145],jb.roomName(rpc),math.floor((rpc.p or 0)*100+0.5),rpc.blocked and(Tse[4146]..rpc.blocked..Tse[2763])or Tse[1020]))
end
end
if#ppc>0 then
F.log(1,Tse[4036],Tse[4147]..table.concat(ppc,Tse[2477]))
end
F.saveNow()
F.status(Tse[3169],Tse[4148]..Qoc.d)
local spc=type(Koc.selected_next)==Tse[2101]and Koc.selected_next.choice_str and tostring(Koc.selected_next.choice_str)or nil
local tpc={tostring(Qoc.key)}
if spc and spc~=tostring(Qoc.key)and not Moc then
table.insert(tpc,spc)
end
for upc,vpc in ipairs(tpc)do
if upc==2 then
local wpc
for xpc,ypc in ipairs(jb.rooms(Koc))do
if tostring(ypc.key)==vpc then
wpc=ypc
end
end
F.log(1,Tse[4036],string.format(Tse[4149],vpc,wpc and jb.roomName(wpc)or Tse[2337]))
end
local zpc,Apc=F.request(Tse[4150],Tse[4151],vpc)
local Bpc=U.now()
while F.alive and U.now()-Bpc<15 do
task.wait(1)
end
if not F.alive then
return true
end
F.log(1,Tse[4036],string.format(Tse[4152],vpc,tostring(Apc)))
end
jb.logState(Koc,Tse[4153])
P.pending=nil
if not Moc then
W.rec(Tse[2821]).restUntil=os.time()+900
end
F.saveSoon()
return false
end
function jb.chain()
task.wait(4)
local Cpc=jb.data()
if not(Cpc and Cpc._started)then
return false
end
return jb.enter(Cpc,O.dungeonValue,true)
end
jb.WAY_WORDS={fast=Tse[4154],balanced=Tse[3936],box=Tse[3831]}
function jb.ways(Dpc)
local function Epc(Fpc,Gpc,Hpc)
local Ipc=table.clone(Dpc)
Ipc.zone,Ipc.placeAll=Gpc,Hpc
return{style=Fpc,info=Ipc}
end
local Jpc=bb.forcedWay()
if Jpc then
return{Epc(Jpc,Jpc==Tse[3806],Jpc==Tse[3807]and Tse[3541]or nil)}
end
local Kpc={Epc(Tse[3807],false,Tse[3541]),Epc(Tse[3845],false,nil)}
if O.killZone~=false then
table.insert(Kpc,Epc(Tse[3806],true,nil))
end
return Kpc
end
jb.ROOM_K_MAX=6
function jb.roomK(Lpc)
local Mpc=Lpc~=nil and type(P.dg.roomK)==Tse[2101]and P.dg.roomK[tostring(Lpc)]or nil
return type(Mpc)==Tse[2101]and tonumber(Mpc.k)or 1
end
function jb.applyK(Npc,Opc)
local Ppc=jb.roomK(Opc)
if Npc and Ppc>1 then
Npc.hpScale=(tonumber(Npc.hpScale)or 1)*Ppc
Npc.roomK=Ppc
end
return Ppc
end
function jb.roomLearn(Qpc)
if Qpc or bb.kind~=Tse[2122]or bb.roomLearned then
return
end
local Rpc=P.dg.room
local Spc,Tpc=bb.pred,bb.calRun
if type(Rpc)~=Tse[2101]or Rpc.seed==nil or type(Spc)~=Tse[2101]or not Spc.won or type(Tpc)~=Tse[2101]then
return
end
local function Upc(Vpc,Wpc)
return type(Vpc)==Tse[2101]and tonumber(Vpc[Wpc]or Vpc[tostring(Wpc)])or nil
end
local Xpc={}
for Ypc=2,bb.wave()do
local Zpc,_pc=Upc(Tpc.alive,Ypc),Upc(Spc.aliveAt,Ypc)
if Zpc and _pc and Zpc>0 and _pc>0 then
table.insert(Xpc,Zpc/_pc)
end
end
if#Xpc<3 then
return
end
table.sort(Xpc)
local aqc=Xpc[math.ceil(#Xpc/2)]
bb.roomLearned=true
if aqc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==Tse[2101]and P.dg.roomK or{}
local bqc=tostring(Rpc.seed)
local cqc=P.dg.roomK[bqc]
local dqc=math.min(jb.ROOM_K_MAX,jb.roomK(bqc)*aqc)
P.dg.roomK[bqc]={k=dqc,n=(type(cqc)==Tse[2101]and tonumber(cqc.n)or 0)+1,at=os.time(),d=Rpc.d}
bb.roomKUp=true
local eqc={}
for fqc,gqc in pairs(P.dg.roomK)do
table.insert(eqc,{s=fqc,at=type(gqc)==Tse[2101]and tonumber(gqc.at)or 0})
end
table.sort(eqc,function(hqc,iqc)
return hqc.at>iqc.at
end)
for jqc=31,#eqc do
P.dg.roomK[eqc[jqc].s]=nil
end
F.log(1,Tse[4036],string.format(Tse[4155],tostring(Rpc.d),aqc,dqc))
end
function jb.roomDone(kqc)
pcall(jb.roomLearn,kqc)
if type(P.simTeam)==Tse[2101]and type(P.simTeam.dg)==Tse[2101]then
P.simTeam.dg.stale=true
end
P.dg.playLast=nil
local lqc=tonumber(type(bb.ld._dungeon)==Tse[2101]and bb.ld._dungeon.depth)or(P.pending and tonumber(P.pending.depth))or 1
local mqc=tostring(math.min(4,math.max(1,math.ceil(lqc/5))))
local nqc=P.dg.depth[mqc]or{runs=0,wins=0}
nqc.runs,nqc.wins=(tonumber(nqc.runs)or 0)+1,(tonumber(nqc.wins)or 0)+(kqc and 1 or 0)
P.dg.depth[mqc]=nqc
if bb.pred and bb.pred.won==false then
local oqc=type(P.dg.lossCalls)==Tse[2101]and P.dg.lossCalls or{}
oqc.n,oqc.won=(tonumber(oqc.n)or 0)+1,(tonumber(oqc.won)or 0)+(kqc and 1 or 0)
P.dg.lossCalls=oqc
end
local pqc=jb.data()
local qqc,rqc,sqc=jb.res(pqc)
jb.note(string.format(Tse[4156],lqc,jb.ROOMS,kqc and Tse[4157]or Tse[2847],qqc,rqc,sqc,jb.lives(pqc)))
P.dg.teams=type(P.dg.teams)==Tse[2101]and P.dg.teams or{}
local tqc=P.dg.teams[W.teamSig()]or{w=0,l=0}
if kqc then
tqc.w=(tonumber(tqc.w)or 0)+1
else
tqc.l=(tonumber(tqc.l)or 0)+1
end
P.dg.teams[W.teamSig()]=tqc
if kqc then
P.dg.lives=5
elseif P.dg.room and P.dg.room.d==lqc then
P.dg.lost=P.dg.lost or{}
local uqc,vqc=tostring(P.dg.room.seed),W.teamSig()
P.dg.lost[uqc]=P.dg.lost[uqc]or{}
P.dg.lost[uqc][vqc]=(P.dg.lost[uqc][vqc]or 0)+1
end
end
function jb.text()
if not O.dungeon then
return Tse[3172]
end
local wqc=jb.data()
if not wqc then
return Tse[4158]
end
if not wqc._started then
return O.dungeonStart and Tse[4159]or Tse[4160]
end
local xqc,yqc,zqc=jb.res(wqc)
local Aqc,Bqc={},{}
for Cqc,Dqc in pairs(jb.items(wqc))do
local Eqc=tostring((jb.item(Cqc)or{}).name or Cqc)..(Dqc>1 and(Tse[2680]..Dqc)or Tse[1020])
table.insert(jb.isCurse(Cqc)and Bqc or Aqc,Eqc)
end
local Fqc={string.format(Tse[4161],tostring(jb.depth(wqc)or Tse[2337]),jb.ROOMS,jb.lives(wqc),xqc,yqc,zqc,jb.luck(wqc))}
table.insert(Fqc,Tse[4162]..(#Aqc>0 and table.concat(Aqc,Tse[2214])or Tse[2683])..Tse[4163]..(#Bqc>0 and table.concat(Bqc,Tse[2214])or Tse[2683]))
table.insert(Fqc,Tse[4164]..jb.fxText(jb.fx(wqc)))
local Gqc=jb._pick and jb._pick.x
if Gqc then
table.insert(Fqc,string.format(Tse[4165],jb.roomName(Gqc),math.floor(Gqc.p*100+0.5)))
end
for Hqc,Iqc in ipairs(P.dg.log)do
if Hqc<=4 then
table.insert(Fqc,os.date(Tse[2850],Iqc.at)..Iqc.msg)
end
end
return table.concat(Fqc,Tse[2111])
end
bb.refused,bb.spent,bb.actions={},0,{}
bb.waveMax={}
bb.BAN_MAX=3600
function bb.mapKey()
return tostring(bb.ld and bb.ld.map or Tse[2337])..(bb.laneCut and(Tse[4166]..bb.laneCut)or Tse[1020])
end
function bb.label()
if bb.kind==Tse[2122]then
local Jqc=type(bb.ld._dungeon)==Tse[2101]and bb.ld._dungeon.depth or Tse[2337]
return string.format(Tse[4167],tostring(Jqc),jb.ROOMS,tostring(bb.ld._location_name or bb.ld.map or Tse[2337]))
end
if bb.kind==Tse[2556]then
return string.format(Tse[4168],tostring(bb.ld._infinite_tower_floor or Tse[2337]),tostring(bb.ld._difficulty or Tse[1025]),tostring(bb.ld.name or bb.ld.map or Tse[2337]))
end
if bb.kind==Tse[2557]then
local Kqc=type(bb.ld._tournament)==Tse[2101]and bb.ld._tournament or{}
return string.format(Tse[4169],tostring(Kqc.tournament_id or Tse[2337]),W.tnWords({score=Kqc.score_type,limit=tonumber(Kqc.level_time_limit),traitless=Kqc.traitless}))
end
return W.levelName(bb.ld.id or Tse[2337])..(bb.ld._difficulty and(Tse[2791]..bb.ld._difficulty..Tse[2763])or Tse[1020])
