function bb.buildPath()
bb.samples={}
local Mqc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Mqc then
return
end
for Nqc,Oqc in pairs(Mqc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Nqc.Name])then
local Pqc={}
for Qqc,Rqc in ipairs(Oqc.points or{})do
table.insert(Pqc,Rqc.part.Position)
end
local Sqc=0
for Tqc=2,#Pqc do
Sqc=Sqc+(Pqc[Tqc]-Pqc[Tqc-1]).Magnitude
end
local Uqc=0
for Vqc=2,#Pqc do
local Wqc,Xqc=Pqc[Vqc-1],Pqc[Vqc]
local Yqc=(Xqc-Wqc).Magnitude
local Zqc=math.max(1,math.floor(Yqc/2))
for _qc=0,Zqc-1 do
local arc=Wqc:Lerp(Xqc,_qc/Zqc)
table.insert(bb.samples,{pos=arc,prog=(Uqc+Yqc*_qc/Zqc)/math.max(1,Sqc),lane=Nqc.Name})
end
Uqc=Uqc+Yqc
end
if Pqc[#Pqc]then
table.insert(bb.samples,{pos=Pqc[#Pqc],prog=1,lane=Nqc.Name})
end
end
end
pcall(bb.readHidden,Mqc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local brc=tonumber(bb.ld and bb.ld._portal_lanes)
local crc=gb.laneList(bb.samples)
if brc and brc>=1 and crc and#crc>brc then
bb.laneWant=brc
end
bb.laneTotal=crc and#crc or 1
bb.countLanes()
end
function bb.readHidden(drc)
local erc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(erc)~=Tse[2101]or not next(erc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local frc
for grc,hrc in pairs(drc)do
if erc[grc.Name]and type(hrc.points)==Tse[2101]and#hrc.points>=2 then
local irc={}
for jrc,krc in ipairs(hrc.points)do
irc[jrc]=U.flat(krc.part.Position)
end
local lrc={}
for mrc,nrc in ipairs(bb.samples)do
local orc=tostring(nrc.lane)
lrc[orc]=lrc[orc]or{}
table.insert(lrc[orc],nrc)
end
local prc,qrc
for rrc,trc in pairs(lrc)do
local urc=0
for vrc=1,#irc,math.max(1,math.floor(#irc/20))do
local wrc=math.huge
for xrc,yrc in ipairs(trc)do
local zrc=(U.flat(yrc.pos)-irc[vrc]).Magnitude
if zrc<wrc then
wrc=zrc
end
end
urc=urc+wrc
end
if not qrc or urc<qrc then
prc,qrc=rrc,urc
end
end
local Arc,Brc,Crc,Drc,Erc,Frc={},nil,nil,nil,0,0
for Grc,Hrc in ipairs(irc)do
local Irc,Jrc=nil,math.huge
for Krc,Lrc in ipairs(lrc[prc])do
local Mrc=(U.flat(Lrc.pos)-Hrc).Magnitude
if Mrc<Jrc then
Jrc,Irc=Mrc,Lrc.prog
end
end
Frc=math.max(Frc,Jrc)
if Crc then
local Nrc=Irc-Crc
local Orc=(Nrc>0.002 and 1)or(Nrc< -0.002 and-1)or Drc
if Drc and Orc and Orc~=Drc then
table.insert(Arc,math.floor(Crc*1000+0.5)/1000)
end
Drc,Erc=Orc or Drc,Erc+math.abs(Nrc)
else
Brc=Irc
end
Crc=Irc
if Grc%50==0 then
task.wait()
end
end
if Crc and Frc<=8 then
table.insert(Arc,math.floor(Crc*1000+0.5)/1000)
frc=frc or{}
frc[grc.Name]={from=math.floor((Brc or 0)*1000+0.5)/1000,len=math.floor(Erc*1000+0.5)/1000,turns=Arc,road=prc}
end
end
end
if not frc then
return
end
local Prc=bb.ld.map
P.maps[Prc]=P.maps[Prc]or{}
local Qrc=P.maps[Prc].hidden
P.maps[Prc].hidden=frc
if type(Qrc)~=Tse[2101]then
for Rrc,Src in pairs(frc)do
F.log(1,Tse[2770],string.format(Tse[4171],Rrc,Src.len,tostring(Src.road),math.floor((#Src.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local Trc,Urc,Vrc={},0,0
for Wrc,Xrc in ipairs(bb.samples)do
local Yrc=tostring(Xrc.lane)
if not Trc[Yrc]then
Urc=Urc+1
end
Trc[Yrc]=(Trc[Yrc]or 0)+1
Vrc=Vrc+1
end
bb.laneCount={n=Urc,by=Trc,avg=Urc>0 and Vrc/Urc or 1}
if Urc>=2 then
local Zrc,_rc=pcall(gb.laneSep,bb.samples)
local asc=P.maps[bb.mapKey()]
if Zrc and _rc and type(asc)==Tse[2101]then
asc.sep=_rc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local bsc,csc={},0
for dsc,esc in ipairs(workspace._UNITS:GetChildren())do
local fsc=esc:FindFirstChild(Tse[2165])
if fsc and fsc:FindFirstChild(Tse[4172])and fsc.player.Value==nil and fsc:FindFirstChild(Tse[4173])and esc:FindFirstChild(Tse[3359])then
local gsc=tostring(fsc.lane.Value)
if not bsc[gsc]then
bsc[gsc]=true
csc=csc+1
end
end
end
if csc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Tse[2770],Tse[4174])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if csc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local hsc,isc={},{}
for jsc,ksc in ipairs(bb.samples)do
if bsc[tostring(ksc.lane)]then
table.insert(hsc,ksc)
end
end
if#hsc==0 then
bb.laneWant=nil
return true
end
for lsc in pairs(bsc)do
table.insert(isc,lsc)
end
table.sort(isc)
bb.samples,bb.laneCut=hsc,table.concat(isc,Tse[2416])
bb.countLanes()
local msc,nsc=pcall(bb.buildCandidates)
if not msc then
F.log(1,Tse[2488],Tse[4175]..tostring(nsc))
end
F.log(1,Tse[2770],string.format(Tse[4176],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local osc,psc=pcall(bb.planSpots)
bb.planning=nil
if not osc then
F.log(1,Tse[2488],Tse[4177]..tostring(psc))
end
end)
end
return true
end
function bb.buildWaves()
local qsc=bb.ld
local rsc=qsc and qsc._dungeon and type(qsc._override_waves)==Tse[2101]and qsc._override_waves or nil
local ssc=qsc and N.Waves[(rsc and rsc.template)or qsc.waves or qsc.id]
local tsc
if type(ssc)==Tse[2101]then
tsc=ssc.override_waves or ssc.waves
if not tsc and ssc.template and N.Waves[ssc.template]then
tsc=N.Waves[ssc.template].waves or N.Waves[ssc.template].override_waves
end
end
bb.waveList=U.list(tsc)
bb.infinite=qsc and(qsc._gamemode==Tse[2121]or qsc.infinite)and gb.unbound(qsc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(qsc and type(qsc._dungeon)==Tse[2101]and 15)or tonumber(qsc and qsc._override_infinite_bound_waves)or gb.boundEnd(qsc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(usc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[usc]=bb.infWaveAt[usc]or U.now()
bb.infExtend()
if O.trainLeave and not bb.stopping then
local vsc,wsc=pcall(bb.trainLeave,usc)
if not vsc then
F.log(1,Tse[2488],Tse[4178]..tostring(wsc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Tse[3653]and bb.kind~=Tse[2557]then
local xsc,ysc=pcall(bb.infStop,usc)
if not xsc then
F.log(1,Tse[2488],Tse[4179]..tostring(ysc))
end
end
local zsc=W.infTier(usc-1)
if zsc<=0 or zsc==bb.infTierSeen then
return
end
bb.infTierSeen=zsc
task.delay(5,function()
if not F.alive then
return
end
local Asc=N.prof()
local Bsc=Asc and Asc.daily_infinite_reward_claims and Asc.daily_infinite_reward_claims[bb.ld.id]
local Csc=type(Bsc)==Tse[2101]and(tonumber(Bsc.highest_claimed_wave)or 0)>=zsc and os.time()-(tonumber(Bsc.highest_claim_time)or 0)<900
if Csc then
P.infLive=true
end
F.log(1,Tse[2770],string.format(Tse[4180],zsc,Csc and Tse[4181]or Tse[4182]))
end)
end
function bb.infStop(Dsc)
local Esc=0
for Fsc,Gsc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
Esc=math.max(Esc,tonumber(Gsc.wave)or 0)
end
if Esc<=0 or Dsc<=Esc+1 then
return
end
local Hsc=P.train.on
if bb.trainee and Hsc and Hsc.have+(Hsc.got or 0)+(bb.trainTk or 0)<Hsc.need then
return
end
if not ab.every(Tse[4183],60)then
return
end
local Isc=W.rec(bb.key)
local Jsc=tonumber(Isc.timed)or 0
local Ksc=W.INF_PAY
local Lsc
if Dsc>=(Ksc.cap+Ksc.less)/Ksc.per then
Lsc=0
else
local Msc=bb.infWaveAt or{}
local Nsc,Osc=Msc[Dsc],Msc[Dsc-5]
if Nsc and Osc and Nsc>Osc then
Lsc=Ksc.per*5/((Nsc-Osc)/60)
end
if not Lsc then
Lsc=(Jsc>0 and(Isc.sec or 0)>0)and math.max(0.5,(Isc.gems or 0)/(Isc.sec/60))or 2.5
end
end
local Psc=pcall(W.pick)
local Qsc
for Rsc,Ssc in ipairs(Psc and W.lastScored or{})do
if Ssc.kind~=Tse[2121]and(not Qsc or(Ssc.score or 0)>(Qsc.score or 0))then
Qsc=Ssc
end
end
if not Qsc or(Qsc.score or 0)<=Lsc then
return
end
bb.stopping=true
F.log(1,Tse[2770],string.format(Tse[4184],Dsc,Lsc,Qsc.score,Qsc.label))
bb.sellAll()
end
function bb.trainLeave(Tsc)
local Usc=P.train.on
if not(bb.infinite and bb.trainee and Usc)then
return
end
bb.trainCount()
local Vsc=Usc.have+(Usc.got or 0)+(bb.trainTk or 0)
if Vsc<Usc.need then
return
end
local Wsc,Xsc,Ysc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if Wsc and(Xsc or 0)>0 and Ysc>0 and Tsc<=Ysc then
F.status(Tse[3323],string.format(Tse[4185],V.name(Usc.id),Usc.what,Ysc))
return
end
bb.stopping=true
F.log(1,Tse[2770],string.format(Tse[4186],V.name(Usc.id),Usc.what,U.fmt(Vsc),U.fmt(Usc.need),Tsc))
bb.sellAll()
end
function bb.sellAll()
