table.insert(Ctc,{m=Htc,pos=Htc.HumanoidRootPart.Position,prog=Ptc,lane=Rtc,hp=Ttc,red=Utc,fly=Wtc,soar=Xtc,sh=Ytc,boss=Ztc,uid=Itc.id.Value})
