end
bb.hpAlive,bb.teamDps=kuc,luc
bb.clearSec=kuc>0 and(luc>0 and kuc/luc or math.huge)or 0
bb.waveMax[iuc]=math.max(bb.waveMax[iuc]or 0,juc)
bb.front=juc
bb.pressure=math.max(bb.waveMax[iuc]or 0,bb.waveMax[iuc-1]or 0)
bb.depth=bb.coverage(Dtc,Ctc)
local uuc=U.now()
