function bb.valid(Zuc,_uc,avc)
local bvc=N.PC.raycast(Zuc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not bvc then
return nil
end
if not N.PC.is_valid_raycast_hit(bvc.Instance,_uc)then
return nil
end
local cvc=bvc.Position
if bb.blockedSpot(cvc)then
return nil
end
local dvc=(tonumber(_uc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(dvc*2,2.5,dvc*2)
bb.probe.CFrame=CFrame.new(cvc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local evc=U.flat(cvc)
local fvc=bb.grifZone
if fvc and type(_uc)==Tse[2101]and _uc.id~=V.GRIF.egg and not V.sacFodder(_uc.id)and(evc-fvc.p).Magnitude<=fvc.r+1.5 then
return nil
end
for gvc,hvc in ipairs(bb.mine or{})do
local ivc=hvc:FindFirstChild(Tse[4207])
local jvc=ivc and ivc.Position or hvc:GetPivot().Position
local kvc=ivc and math.max(ivc.Size.X,ivc.Size.Z)/2 or 1.5
if(evc-U.flat(jvc)).Magnitude<dvc+kvc then
return nil
end
end
if not avc then
for lvc,mvc in ipairs(bb.blockers())do
if(evc-mvc.p).Magnitude<dvc+mvc.r then
return nil
end
end
end
return cvc
end
function bb.buildCandidates()
bb.cands={}
local nvc={}
for ovc=1,#bb.samples,3 do
local pvc=bb.samples[ovc]
local qvc=bb.samples[math.min(#bb.samples,ovc+1)]
local rvc=U.flat(qvc.pos-pvc.pos)
if rvc.Magnitude<0.01 then
rvc=Vector3 .new(1,0,0)
end
rvc=rvc.Unit
local tvc=Vector3 .new(-rvc.Z,0,rvc.X)
for uvc,vvc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for wvc,xvc in ipairs({1,-1})do
local yvc=pvc.pos+tvc*vvc*xvc
local zvc=string.format(Tse[4204],math.floor(yvc.X/1.5),math.floor(yvc.Z/1.5))
if not nvc[zvc]then
nvc[zvc]=true
table.insert(bb.cands,yvc)
end
end
end
end
end
function bb.coverage(Avc,Bvc)
local Cvc={}
for Dvc,Evc in ipairs(Avc)do
local Fvc=Evc._stats
if not V.isFarm(Fvc.id.Value)and Fvc:FindFirstChild(Tse[2354])then
table.insert(Cvc,{p=U.flat(Evc:GetPivot().Position),r=Fvc.range.Value*(V.SUMMONER[Fvc.id.Value]and V.SUMMONER[Fvc.id.Value].reach or 1),air=bb.canAir(Evc)})
end
end
local Gvc,Hvc=0,0
if#Cvc>0 then
for Ivc,Jvc in ipairs(bb.samples)do
if Jvc.prog>Hvc then
local Kvc=U.flat(Jvc.pos)
for Lvc,Mvc in ipairs(Cvc)do
if(Kvc-Mvc.p).Magnitude<=Mvc.r then
if Jvc.prog>Gvc then
Gvc=Jvc.prog
end
if Mvc.air then
Hvc=Jvc.prog
break
end
end
end
end
end
end
local Nvc,Ovc={},bb.laneCount
if Ovc and Ovc.n>=2 and#Cvc>0 then
local Pvc={}
for Qvc,Rvc in ipairs(bb.samples)do
local Svc=U.flat(Rvc.pos)
for Tvc,Uvc in ipairs(Cvc)do
if(Svc-Uvc.p).Magnitude<=Uvc.r then
local Vvc=tostring(Rvc.lane)
Pvc[Vvc]=(Pvc[Vvc]or 0)+1
if Rvc.prog>(Nvc[Vvc]or 0)then
Nvc[Vvc]=Rvc.prog
end
break
end
end
end
local Wvc,Xvc={},0
for Yvc,Zvc in pairs(Ovc.by)do
Wvc[Yvc]=(Pvc[Yvc]or 0)/math.max(1,Zvc)
Xvc=math.max(Xvc,Wvc[Yvc])
end
bb.laneW={}
for _vc,awc in pairs(Ovc.by)do
bb.laneW[_vc]=(Ovc.avg/math.max(1,awc))*(1+1.5*(Xvc>0 and(1-Wvc[_vc]/Xvc)or 0))
end
bb.laneFrac=Wvc
else
bb.laneW,bb.laneFrac=nil,nil
