local bwc,cwc,dwc
if#Cvc>0 then
for ewc,fwc in ipairs(Bvc)do
local gwc=(bb.laneW and fwc.lane)and(Nvc[tostring(fwc.lane)]or 0)or Gvc
if fwc.hp>0 and fwc.prog>gwc+0.02 and fwc.prog>(bwc or 0)then
bwc,dwc=fwc.prog,bb.laneW and fwc.lane or nil
end
if fwc.hp>0 and fwc.fly and fwc.prog>Hvc+0.02 then
cwc=true
end
end
end
local hwc= #Cvc>0 and(bb.pressure or 0)>=Gvc-0.08
return{covEnd=Gvc,airEnd=Hvc,leak=bwc,leakLane=dwc,covL=Nvc,airLeak=cwc,push=hwc,units= #Cvc}
end
function bb.needLastLine(iwc)
