local WMc=gb.runRaw(mMc,nMc,{hpMul=UMc,layout=GMc(PMc),bg=true})
QMc,RMc,SMc=QMc+gb.objective(WMc),RMc+(tonumber(WMc.kills)or 0),SMc+(tonumber(WMc.wave)or 0)
task.wait(math.clamp((os.clock()-VMc)*3,0.25,jMc.pauseMax or 1.5))
if not lMc()then
return nil
end
end
tMc.n,tMc.run=tMc.n+1,tMc.run+1
return QMc/ #rMc*100+IMc(PMc),RMc/ #rMc,SMc/ #rMc
end
local function XMc(YMc)
local ZMc={}
for _Mc,aNc in pairs(YMc)do
ZMc[_Mc]=aNc
end
return ZMc
end
local function bNc(cNc,dNc,eNc)
for fNc,gNc in pairs(cNc)do
if fNc~=dNc and(U.flat(gNc)-U.flat(eNc)).Magnitude<4.5 then
return true
end
end
return false
end
local hNc={spots=XMc(oMc.spots)}
hNc.s,hNc.kills,hNc.wave=OMc(hNc.spots)
if not hNc.s then
return bb.studyEnd(tMc,jMc,nil)
end
tMc.baseKills,tMc.baseWave=hNc.kills,hNc.wave
tMc.bestKills,tMc.bestWave=hNc.kills,hNc.wave
if sMc and sMc.aside==nil then
local iNc,jNc=XMc(hNc.spots),0
for kNc,lNc in ipairs(jMc.attackers)do
local mNc=sMc.spots[lNc.id]
local nNc=type(mNc)==Tse[2101]and tonumber(mNc[1])and tonumber(mNc[3])and bb.nearSpot(lNc.spots,tonumber(mNc[1]),tonumber(mNc[3]))or nil
if nNc and nNc~=iNc[lNc.id]and not bNc(iNc,lNc.id,nNc)then
iNc[lNc.id]=nNc
jNc=jNc+1
end
end
if jNc>0 then
local oNc,pNc,qNc=OMc(iNc)
if not oNc then
return bb.studyEnd(tMc,jMc,hNc)
end
if oNc>hNc.s then
hNc={spots=iNc,s=oNc,kills=pNc,wave=qNc}
tMc.bestKills,tMc.bestWave=pNc,qNc
end
end
end
local rNc,sNc=U.now(),tMc.run
local function tNc(uNc)
if not(uNc.s and uNc.s>hNc.s+math.max(50,math.abs(hNc.s)*0.005))then
return false
end
hNc=uNc
tMc.bestKills,tMc.bestWave,tMc.better=uNc.kills,uNc.wave,(tMc.better or 0)+1
pcall(bb.bookSave,mMc,jMc,hNc,tMc)
return true
end
local function vNc()
if tMc.run-sNc>=60 or U.now()-rNc>240 then
rNc,sNc=U.now(),tMc.run
F.log(1,Tse[2855],bb.studyWords(tMc))
end
end
local wNc={hNc}
for xNc,yNc in ipairs(jMc.attackers)do
local zNc={}
for ANc,BNc in ipairs(wNc)do
table.insert(zNc,BNc)
for CNc,DNc in ipairs(uMc[yNc.id]or{})do
if DNc~=BNc.spots[yNc.id]and not bNc(BNc.spots,yNc.id,DNc)then
local ENc=XMc(BNc.spots)
ENc[yNc.id]=DNc
local FNc,GNc,HNc=OMc(ENc)
if not FNc then
return bb.studyEnd(tMc,jMc,hNc)
end
local INc={spots=ENc,s=FNc,kills=GNc,wave=HNc}
table.insert(zNc,INc)
tNc(INc)
vNc()
end
end
end
table.sort(zNc,function(JNc,KNc)
return(JNc.s or-1e18)>(KNc.s or-1e18)
end)
wNc={}
for LNc=1,math.min(bb.STUDY_BEAM,#zNc)do
table.insert(wNc,zNc[LNc])
end
end
local MNc={}
for NNc,ONc in ipairs(jMc.attackers)do
if uMc[ONc.id]and#uMc[ONc.id]>0 then
table.insert(MNc,ONc.id)
end
end
while lMc()and#MNc>0 do
local PNc=XMc(hNc.spots)
for QNc=1,math.min(2,#MNc)do
local RNc=MNc[math.random(#MNc)]
local SNc=uMc[RNc]
local TNc=SNc[math.random(#SNc)]
if not bNc(PNc,RNc,TNc)then
PNc[RNc]=TNc
end
end
local UNc,VNc,WNc=OMc(PNc)
if not UNc then
break
end
tNc({spots=PNc,s=UNc,kills=VNc,wave=WNc})
vNc()
end
bb.studyEnd(tMc,jMc,hNc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(XNc,YNc)
local ZNc=N.PC.raycast(XNc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not ZNc then
return nil
end
if not N.PC.is_valid_raycast_hit(ZNc.Instance,YNc)then
return nil
end
local _Nc=ZNc.Position
if bb.blockedSpot(_Nc)then
return nil
end
local aOc=(tonumber(YNc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(aOc*2,2.5,aOc*2)
bb.probe.CFrame=CFrame.new(_Nc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return _Nc
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==Tse[2557]then
return
end
local bOc=bb.info
local function cOc()
return not F.alive or bb.finished or bb.result or F.where~=Tse[2174]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local dOc,eOc={},{}
for fOc,gOc in ipairs(bb.team or{})do
table.insert(dOc,gOc.u)
if not V.isFarm(gOc.id)and not V.allyBuff(gOc.id)and gOc.uuid~=bb.trainee and V.rows(gOc.id)then
local hOc,iOc=pcall(V.score,gOc.u,bb.mod)
table.insert(eOc,{e=gOc,id=gOc.id,sc=hOc and iOc or 0})
end
end
if#eOc==0 then
return
end
table.sort(eOc,function(jOc,kOc)
return jOc.sc>kOc.sc
end)
local function lOc()
local mOc,nOc={},0
for oOc,pOc in ipairs(eOc)do
for qOc,rOc in ipairs(bb.mine or{})do
local sOc=rOc:FindFirstChild(Tse[2165])
local tOc=sOc and sOc:FindFirstChild(Tse[2478])
if tOc and tOc.Value==pOc.e.uuid and sOc:FindFirstChild(Tse[2479])and sOc.id.Value==pOc.id then
mOc[pOc.id]=rOc:GetPivot().Position
nOc=nOc+1
break
end
end
end
return mOc,nOc
end
local uOc=U.now()
local vOc,wOc=lOc()
while wOc< #eOc and U.now()-uOc<bb.STUDY_INF_WAIT do
task.wait(5)
if cOc()then
return
end
vOc,wOc=lOc()
end
if wOc==0 or cOc()then
return
end
local xOc={}
local function yOc(zOc)
local AOc=zOc.hybrid_placement and not zOc.hill_unit
local BOc=AOc and bb.hybridHill
local COc=((zOc.hill_unit or BOc)and Tse[2881]or(AOc and Tse[4283])or Tse[4284])..Tse[2237]..tostring(zOc.override_hitbox_radius or Tse[1020])
if xOc[COc]then
return xOc[COc]
end
local DOc={}
local EOc=BOc and bb.hillData(zOc)or zOc
for FOc,GOc in ipairs(bb.cands or{})do
local HOc=bb.validOpen(GOc,EOc)
if HOc then
table.insert(DOc,HOc)
end
if FOc%40==0 then
