end
end
xOc[COc]=DOc
return DOc
end
local IOc={info=bOc,team=gb.teamFrom(dOc,bOc.map),key=bb.bookKey(bOc),hard=1,scale=tonumber(bOc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local JOc={spots={},style=Tse[3043],hybridHill=bb.hybridHill and true or false}
for KOc,LOc in ipairs(eOc)do
