function bb.bookSave(UOc,VOc,WOc,XOc)
P.mapBook=type(P.mapBook)==Tse[2101]and P.mapBook or{}
local YOc={}
for ZOc,_Oc in pairs(WOc.spots or{})do
YOc[ZOc]={math.floor(_Oc.X*10+0.5)/10,math.floor(_Oc.Y*10+0.5)/10,math.floor(_Oc.Z*10+0.5)/10}
end
P.mapBook[VOc.key]={spots=YOc,style=VOc.base.style,hp=XOc.hp,n=XOc.n,kills=WOc.kills and math.floor(WOc.kills+0.5)or nil,wave=WOc.wave and math.floor(WOc.wave*10+0.5)/10 or nil,base=XOc.baseWave and math.floor(XOc.baseWave*10+0.5)/10 or nil,label=XOc.label,map=UOc.map,killScore=XOc.kills,at=os.time()}
local aPc={}
for bPc,cPc in pairs(P.mapBook)do
table.insert(aPc,{k=bPc,at=type(cPc)==Tse[2101]and tonumber(cPc.at)or 0})
end
if#aPc>bb.BOOK_MAX then
table.sort(aPc,function(dPc,ePc)
return dPc.at>ePc.at
end)
for fPc=bb.BOOK_MAX+1,#aPc do
P.mapBook[aPc[fPc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(gPc,hPc,iPc)
if type(gPc)~=Tse[2101]or gPc.ended then
return
end
gPc.ended=true
if iPc and hPc then
local jPc=bb.bookFor(hPc.info)
if jPc then
jPc.n=gPc.n
F.saveSoon()
elseif gPc.run>0 then
pcall(bb.bookSave,hPc.info,hPc,iPc,gPc)
end
end
if gPc.run>0 then
F.log(1,Tse[2855],bb.studyWords(gPc))
end
end
function bb.studyReport()
