bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(CPc,DPc)
local EPc=bb.bookKey(CPc)
P.layoutRec=type(P.layoutRec)==Tse[2101]and P.layoutRec or{}
local FPc=P.layoutRec[EPc]
if type(FPc)~=Tse[2101]then
if not DPc then
return nil
end
FPc={at=os.time()}
P.layoutRec[EPc]=FPc
if U.count(P.layoutRec)>80 then
local GPc,HPc
for IPc,JPc in pairs(P.layoutRec)do
local KPc=type(JPc)==Tse[2101]and tonumber(JPc.at)or 0
if not HPc or KPc<HPc then
GPc,HPc=IPc,KPc
end
end
P.layoutRec[GPc]=nil
end
end
return FPc
end
function bb.layoutAdd(LPc,MPc,NPc,OPc,PPc)
LPc.runs,LPc.wins=(tonumber(LPc.runs)or 0)+1,(tonumber(LPc.wins)or 0)+(MPc and 1 or 0)
LPc.sec,LPc.wave=type(LPc.sec)==Tse[2101]and LPc.sec or{},type(LPc.wave)==Tse[2101]and LPc.wave or{}
if MPc and tonumber(NPc)then
table.insert(LPc.sec,math.floor(NPc+0.5))
end
table.insert(LPc.wave,tonumber(OPc)or 0)
if tonumber(PPc)then
LPc.kills=type(LPc.kills)==Tse[2101]and LPc.kills or{}
table.insert(LPc.kills,math.floor(tonumber(PPc)))
while#LPc.kills>bb.LAYOUT_KEEP do
table.remove(LPc.kills,1)
end
end
while#LPc.sec>bb.LAYOUT_KEEP do
table.remove(LPc.sec,1)
end
while#LPc.wave>bb.LAYOUT_KEEP do
table.remove(LPc.wave,1)
end
end
function bb.layoutJudge(QPc,RPc,SPc,TPc,UPc)
UPc=UPc or Tse[4366]
local VPc,WPc=tonumber(QPc and QPc.runs)or 0,tonumber(RPc and RPc.runs)or 0
if VPc<1 or WPc<bb.LAYOUT_CONTROL then
return nil
end
if TPc and type(QPc.kills)==Tse[2101]and type(RPc.kills)==Tse[2101]and#QPc.kills>=1 and#RPc.kills>=bb.LAYOUT_CONTROL then
local XPc,YPc=bb.labMedian(QPc.kills),bb.labMedian(RPc.kills)
if XPc and YPc and XPc<YPc*0.97 and(#QPc.kills>=2 or XPc<YPc*0.85)then
return string.format(Tse[4367],XPc,YPc,UPc)
end
return nil
end
local ZPc,_Pc=(tonumber(QPc.wins)or 0)/VPc,(tonumber(RPc.wins)or 0)/WPc
if not SPc and _Pc>=0.5 then
if ZPc+0.25<_Pc and(VPc>=2 or(ZPc==0 and _Pc>=0.9 and WPc>=3))then
return string.format(Tse[4368],tonumber(QPc.wins)or 0,VPc,VPc==1 and Tse[1020]or Tse[1947],tonumber(RPc.wins)or 0,WPc,UPc)
end
local aQc,bQc=bb.labMedian(QPc.sec),bb.labMedian(RPc.sec)
if aQc and bQc and aQc>bQc*1.10 and(#QPc.sec>=2 or aQc>bQc*1.25)then
return string.format(Tse[4369],math.floor(aQc/60),aQc%60,math.floor(bQc/60),bQc%60,UPc)
end
return nil
end
local cQc,dQc=bb.labMedian(QPc.wave),bb.labMedian(RPc.wave)
if cQc and dQc and cQc<dQc-math.max(1,dQc*0.03)and(VPc>=2 or cQc<dQc*0.85)then
return string.format(Tse[4370],cQc,dQc,UPc)
end
return nil
end
function bb.layoutResult(eQc,fQc)
local gQc=bb.info
local hQc=bb.layoutSrc
if not(gQc and hQc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not gQc.timeLimit then
return
end
local iQc=bb.wave()
local jQc=bb.layoutRecFor(gQc,true)
jQc.at=os.time()
local kQc=gQc.timeLimit~=nil
local lQc=gQc.killScore and true or nil
local mQc=lQc and(bb.killsEnd or bb.realKills())or nil
if hQc==Tse[4336]then
local nQc=bb.bookFor(gQc)
if not nQc then
return
end
nQc.real=type(nQc.real)==Tse[2101]and nQc.real or{}
bb.layoutAdd(nQc.real,eQc,fQc,iQc,mQc)
local oQc=nQc.aside==nil and bb.layoutJudge(nQc.real,jQc.own,kQc,lQc)or nil
if oQc then
nQc.aside={at=os.time(),why=oQc}
F.log(1,Tse[4272],string.format(Tse[4371],oQc))
end
elseif hQc==Tse[3704]then
jQc.hiveUnit=type(jQc.hiveUnit)==Tse[2101]and jQc.hiveUnit or{}
local pQc=jQc.hiveUnit
bb.layoutAdd(pQc,eQc,fQc,iQc,mQc)
local qQc=bb.bookFor(gQc)
local rQc=qQc and type(qQc.real)==Tse[2101]and(tonumber(qQc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local sQc=rQc and qQc.real or jQc.own
local tQc=bb.layoutJudge(pQc,sQc,kQc,lQc,rQc and Tse[4372]or nil)
if tQc then
pQc.aside,pQc.why=os.time(),tQc
F.log(1,Tse[4272],string.format(Tse[4373],tQc))
elseif(tonumber(pQc.runs)or 0)>=bb.HIVE_TRIALS then
local uQc=sQc and bb.layoutJudge(sQc,pQc,kQc,lQc,Tse[4374])
if uQc and qQc and type(bb.hiveUnitPlan)==Tse[2101]then
