qQc.spots[vQc]=wQc
end
qQc.real={runs=pQc.runs,wins=pQc.wins,sec=pQc.sec,wave=pQc.wave,kills=pQc.kills}
qQc.hive,qQc.aside=os.time(),nil
jQc.hiveUnit=nil
F.log(1,Tse[4272],string.format(Tse[4375],uQc))
else
pQc.aside,pQc.why=os.time(),Tse[4376]
F.log(1,Tse[4272],Tse[4377])
end
end
else
jQc[hQc]=type(jQc[hQc])==Tse[2101]and jQc[hQc]or{}
local xQc=jQc[hQc]
bb.layoutAdd(xQc,eQc,fQc,iQc,mQc)
if hQc==Tse[3703]and xQc.aside==nil then
local yQc=bb.layoutJudge(xQc,jQc.own,kQc,lQc)
if yQc then
xQc.aside,xQc.why=os.time(),yQc
F.log(1,Tse[4272],string.format(Tse[4378],yQc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Tse[4379],Tse[4380],Tse[4381],Tse[4382]}
function bb.controlSpot(zQc,AQc)
if not bb.killZone()then
return nil
end
local BQc=gb.holds
if not BQc(zQc.id)or V.toggleOf(zQc.id)then
return nil
end
local CQc,DQc,EQc,FQc=1,0,0,{}
local GQc=bb.hurtSamples()
for HQc,IQc in ipairs(bb.mine or{})do
local JQc=IQc._stats
local KQc=JQc.id.Value
if JQc:FindFirstChild(Tse[2354])and not V.isFarm(KQc)and not V.allyBuff(KQc)then
local LQc,MQc=U.flat(IQc:GetPivot().Position),JQc.range.Value
if BQc(KQc)and not V.toggleOf(KQc)then
EQc=EQc+1
table.insert(FQc,{p=LQc,r=MQc})
else
for NQc,OQc in ipairs(GQc)do
if(U.flat(OQc.pos)-LQc).Magnitude<=MQc then
CQc,DQc=math.min(CQc,OQc.prog),math.max(DQc,OQc.prog)
end
end
end
end
end
if DQc<=CQc then
CQc,DQc=0.75,0.98
end
local PQc=(AQc or EQc)+1
local QQc=({CQc,DQc,(CQc+DQc)/2,CQc-(DQc-CQc)/2})[PQc]
if not QQc then
return nil
end
local RQc=V.range(zQc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local SQc={}
