if(U.flat(ZQc.pos)-VQc).Magnitude<=RQc then
XQc=XQc+1
if math.abs(ZQc.prog-QQc)<=0.05 then
WQc=WQc+1
local _Qc=U.flat(ZQc.pos)
for aRc,bRc in ipairs(FQc)do
