for yRc,zRc in ipairs(kRc)do
if(wRc-zRc.p).Magnitude<=zRc.r then
xRc=xRc+zRc.d
end
end
tRc[uRc]=xRc/lRc
end
local ARc=V.range(hRc.u,math.min(tonumber(jRc)or 0,3,V.rows(hRc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
