if QUc<MUc then
MUc,NUc=QUc,PUc.pos
end
end
local RUc=NUc and U.flat(NUc-LUc)or Vector3 .new(0,0,-1)
return RUc.Magnitude>0.01 and RUc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(SUc,TUc)
