end
local XUc=bb.money()
local YUc=P.caps[SUc.uuid]and bb.count(SUc.uuid)or nil
local ZUc,_Uc=F.request(Tse[4389],Tse[4390],SUc.uuid,N.Util.CFramePLV(VUc,bb.lookAt(VUc)))
if ZUc and _Uc then
if YUc and YUc>=(tonumber(P.caps[SUc.uuid])or math.huge)then
F.log(1,Tse[4211],string.format(Tse[4391],V.name(SUc.id),tostring(P.caps[SUc.uuid])))
P.caps[SUc.uuid],P.capsAt[SUc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(SUc.data.cost or 0)
table.insert(bb.actions,string.format(Tse[4392],V.name(SUc.id)))
