bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=SUc.id,x=math.floor(VUc.X),z=math.floor(VUc.Z),cover=math.floor((WUc or 0)+0.5),why=tostring(TUc):sub(1,90)})
F.status(Tse[4275],string.format(Tse[4394],V.name(SUc.id),TUc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[SUc.uuid]=(bb.placedAt[SUc.uuid]or 0)+1
return true
end
if XUc>=(SUc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[SUc.uuid]=(bb.placeFail[SUc.uuid]or 0)+1
if bb.placeFail[SUc.uuid]>=2 then
bb.noSpot[SUc.uuid]=3
F.log(1,Tse[4211],string.format(Tse[4395],V.name(SUc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if ZUc and XUc>=(SUc.data.cost or 0)and not bb.random then
local aVc=bb.spotKey(VUc)
