if not bb.refusedRun[aVc]then
P.blocked[bVc][aVc]=(tonumber(P.blocked[bVc][aVc])or 0)+1
bb.refusedRun[aVc]=true
P.blockedAt[bVc]=P.blockedAt[bVc]or{}
P.blockedAt[bVc][aVc]=os.time()
end
if bb.unitRefusals[SUc.uuid]>=3 then
local cVc=math.max(1,bb.count(SUc.uuid))
if P.caps[SUc.uuid]~=cVc or not V.learnedCap(SUc.uuid)then
P.caps[SUc.uuid],P.capsAt[SUc.uuid]=cVc,os.time()
F.log(1,Tse[4211],string.format(Tse[4396],V.name(SUc.id),cVc))
end
end
elseif bb.unitRefusals[SUc.uuid]>=3 and(bb.noSpot[SUc.uuid]or 0)<3 then
