end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,Tse[4211],Tse[4399]..aVc..Tse[3029]..V.name(SUc.id))
F.saveSoon()
end
return false
end
function bb.crowded()
