pcall(bb.sampleHelpers)
local mVc=U.now()
local nVc=bb.wave()
local oVc=bb.money()
if not kVc.start and oVc>0 and#bb.mine==0 then
kVc.start=oVc
end
if nVc~=kVc.lastW then
if bb.trialId and nVc>0 then
bb.trialTrace=bb.trialTrace or{}
local pVc,qVc,rVc,sVc=0,{},0,0
for tVc,uVc in ipairs(bb.mine)do
local vVc=uVc._stats
if vVc.id.Value==bb.trialId then
pVc=pVc+1
table.insert(qVc,tostring(vVc.upgrade.Value))
elseif not V.isFarm(vVc.id.Value)then
sVc=sVc+1
end
