function bb.learn()
local rcd=bb.calRun and bb.calRun.potBy
if type(rcd)~=Tse[2101]then
return
end
pcall(bb.sampleHelpers,true)
local scd={}
for tcd,ucd in pairs(bb.ownDealt or{})do
if not V.isFarm(ucd.id)then
scd[ucd.id]=(scd[ucd.id]or 0)+(tonumber(ucd.v)or 0)
end
end
for vcd,wcd in pairs(bb.helperDealt or{})do
if wcd.owner and V.SUMMONER[wcd.owner]and not V.droneHelper(wcd)then
scd[wcd.owner]=(scd[wcd.owner]or 0)+(tonumber(wcd.v)or 0)
end
end
local xcd=type(bb.calRun.potExp)==Tse[2101]and bb.calRun.potExp or{}
local ycd,zcd=0,0
local Acd={}
for Bcd,Ccd in pairs(rcd)do
if Ccd>0 then
ycd,zcd=ycd+(scd[Bcd]or 0),zcd+Ccd
local Dcd=tonumber(xcd[Bcd])or Ccd
if Dcd>0 then
table.insert(Acd,{id=Bcd,r=(scd[Bcd]or 0)/Dcd,w=Dcd})
end
end
end
if ycd<=0 or zcd<=0 then
return
end
table.sort(Acd,function(Ecd,Fcd)
return Ecd.r<Fcd.r
end)
local function Gcd(Hcd)
local Icd,Jcd=0,0
for Kcd,Lcd in ipairs(Acd)do
if Lcd.id~=Hcd then
Icd=Icd+Lcd.w
end
end
if Icd<=0 then
return nil
end
for Mcd,Ncd in ipairs(Acd)do
if Ncd.id~=Hcd then
Jcd=Jcd+Ncd.w
if Jcd>=Icd/2 then
return Ncd.r
end
end
end
end
bb.lastEff={}
for Ocd,Pcd in pairs(rcd)do
local Qcd=Gcd(Ocd)
if Pcd>0 and Pcd/zcd>0.02 and Qcd and Qcd>0 then
local Rcd=P.learn[Ocd]or{eff=1,n=0,v=6}
V.learnUp(Ocd,Rcd)
local Scd=math.max(0.02,0.25*math.sqrt(30/(30+Rcd.n)))
local Tcd=U.clamp(((scd[Ocd]or 0)/Pcd)/Qcd,0.2,6)
bb.lastEff[Ocd]=math.floor(Tcd*1000+0.5)/1000
Rcd.eff=Rcd.eff+(Tcd-Rcd.eff)*Scd
Rcd.n=Rcd.n+1
P.learn[Ocd]=Rcd
end
end
local Ucd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Ucd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==Tse[2101]and P.mapLearn or{}
local Vcd=type(P.mapLearn[Ucd])==Tse[2101]and P.mapLearn[Ucd]or{}
for Wcd,Xcd in pairs(bb.lastEff)do
local Ycd=type(Vcd[Wcd])==Tse[2101]and Vcd[Wcd]or{eff=Xcd,n=0,v=6}
if(tonumber(Ycd.v)or 0)<4 then
Ycd.eff,Ycd.v=(tonumber(Ycd.eff)or Xcd)*V.secRescale(Wcd),4
end
if(tonumber(Ycd.v)or 0)<5 then
Ycd.eff,Ycd.v=(tonumber(Ycd.eff)or Xcd)*(V.sumRescale(Wcd)or 1),5
end
if(tonumber(Ycd.v)or 0)<6 then
Ycd.eff,Ycd.v=(tonumber(Ycd.eff)or Xcd)*(1-(V.SUMMONER[Wcd]and V.SUMMONER[Wcd].droneShare or 0)),6
end
local Zcd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Ycd.n)or 0))))
Ycd.eff=(tonumber(Ycd.n)or 0)==0 and Xcd or((tonumber(Ycd.eff)or Xcd)+(Xcd-(tonumber(Ycd.eff)or Xcd))*Zcd)
Ycd.n=(tonumber(Ycd.n)or 0)+1
Vcd[Wcd]=Ycd
end
Vcd._at=os.time()
P.mapLearn[Ucd]=Vcd
if U.count(P.mapLearn)>80 then
local _cd,bdd
for cdd,ddd in pairs(P.mapLearn)do
if not bdd or(tonumber(ddd._at)or 0)<bdd then
_cd,bdd=cdd,tonumber(ddd._at)or 0
end
end
P.mapLearn[_cd]=nil
end
end
end
