bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Pid,Qid)
local Rid=(Qid.t or 0)-(Pid.t or 0)
if Rid<bb.BASE_WIN-1 then
return false
end
local Sid=((tonumber(Pid.base)or 0)-(tonumber(Qid.base)or 0))/Rid
if Sid<=0 or(tonumber(Qid.base)or 0)<=0 then
return false
end
local Tid=Qid.base/Sid
local Uid,Vid=0,0
local Wid,Xid=Pid.foes or{},Qid.foes or{}
for Yid,Zid in pairs(Xid)do
if Zid.prog>=bb.BASE_END then
Uid=Uid+Zid.hp
local ajd=Wid[Yid]
if ajd then
Vid=Vid+math.max(0,ajd.hp-Zid.hp)
end
end
end
for bjd,cjd in pairs(Wid)do
if cjd.prog>=bb.BASE_END and not Xid[bjd]then
Vid=Vid+cjd.hp
end
end
if Uid<=0 then
return false
end
local djd=Vid/Rid
local ejd=djd>0 and Uid/djd or math.huge
local fjd={baseTime=Tid,loss=Sid,atEnd=Uid,rate=djd,killTime=ejd}
return Tid<bb.BASE_SOON and ejd>Tid*bb.BASE_MARGIN,fjd
end
