if bkd.m then
Zjd[bkd.m]=true
local ckd,dkd=tonumber(bkd.hp)or 0,tonumber(bkd.prog)or 0
local ekd=Yjd[bkd.m]
if not ekd then
Yjd[bkd.m]={t=Xjd,hp=ckd,prog=dkd}
else
