function bb.drownTick()
local tod,uod,vod,wod,xod=pcall(bb.drownBoss)
if not(tod and uod)then
bb.drownTarget=nil
return
end
bb.drownTarget=vod and uod or nil
if vod then
return
end
local yod=bb.drownState
if not yod or yod.m~=uod.m then
yod={m=uod.m,moves=0,at=0}
bb.drownState=yod
end
if yod.moves>=bb.DROWN_MOVES or U.now()-yod.at<bb.DROWN_EVERY then
return
end
local zod=1
pcall(function()
zod=N.USC.calculate_spawn_cost_multiplier(N.session())
end)
for Aod,Bod in pairs(xod)do
local Cod={}
for Dod,Eod in ipairs(wod)do
if Eod._stats.id.Value==Aod then
table.insert(Cod,Eod)
end
end
if#Cod>=V.cap(Bod.u)then
local Fod=(tonumber(Bod.data and Bod.data.cost)or 0)*zod
local God,Hod
for Iod,Jod in ipairs(Cod)do
local Kod=Jod._stats
local Lod,Mod=U.flat(Jod:GetPivot().Position),Kod.range.Value
local Nod=false
for Ood,Pod in ipairs(bb.samples)do
if Pod.prog>=uod.prog and(U.flat(Pod.pos)-Lod).Magnitude<=Mod then
Nod=true
break
end
end
local Qod=Kod:FindFirstChild(Tse[4213])and tonumber(Kod.total_spent.Value)or 0
if not Nod and Qod<=2.5*Fod and(not Hod or Qod<Hod)then
God,Hod=Jod,Qod
end
end
if God and bb.money()+gb.SELL_BACK*Hod>=Fod then
yod.at,yod.moves=U.now(),yod.moves+1
local Rod,Sod=F.request(Tse[2284],Tse[2482],God)
if Sod==true then
F.log(1,Tse[4211],string.format(Tse[4716],V.name(Aod),U.fmt(Hod),U.fmt(uod.hp)))
task.wait(0.5)
local Tod,Uod=pcall(bb.place,Bod,Tse[4717])
if not Tod then
F.log(1,Tse[2488],Tse[4718]..tostring(Uod))
end
end
return
end
end
end
end
bb.cashTried=setmetatable({},{__mode=Tse[2487]})
