bb.mergeIds={}
function bb.mergeScan()
bb.mergePlan,bb.mergeIds=nil,{}
if not bb.random then
return
end
local jpd=N.session()
local kpd=false
bb.cloneCard=false
for lpd,mpd in pairs((jpd and jpd.ingame_spells)or{})do
