for ppd,qpd in ipairs(bb.mine or{})do
local rpd=qpd._stats
local spd=rpd.id.Value
if not V.isFarm(spd)and not V.allyBuff(spd)and not V.idol(spd)and rpd:FindFirstChild(Tse[2490])and(opd[spd]or 0)<2 then
local tpd,upd=pcall(bb.liveDps,qpd,spd)
npd[spd]=npd[spd]or{}
table.insert(npd[spd],{m=qpd,lvl=rpd.upgrade.Value,max=rpd.max_upgrade.Value,dps=tpd and upd or 0})
end
end
local vpd={}
for wpd,xpd in ipairs(bb.team or{})do
if xpd.hand then
vpd[xpd.id]=true
end
end
local ypd={}
for zpd,Apd in pairs(npd)do
table.sort(Apd,function(Bpd,Cpd)
if Bpd.dps~=Cpd.dps then
return Bpd.dps>Cpd.dps
end
return Bpd.lvl>Cpd.lvl
end)
table.insert(ypd,{id=zpd,dps=Apd[1].dps*bb.airBoost(Apd[1].m)*bb.reach(Apd[1].m)})
end
table.sort(ypd,function(Dpd,Epd)
return Dpd.dps>Epd.dps
end)
for Fpd=1,math.min(3,#ypd)do
bb.mergeIds[ypd[Fpd].id]=true
end
local Gpd
for Hpd,Ipd in pairs(npd)do
local Jpd=table.clone(Ipd)
table.sort(Jpd,function(Kpd,Lpd)
if Kpd.lvl~=Lpd.lvl then
return Kpd.lvl<Lpd.lvl
end
return Kpd.dps<Lpd.dps
end)
for Mpd,Npd in ipairs(Jpd)do
if Npd.m==bb.freshM and Mpd>1 then
table.remove(Jpd,Mpd)
table.insert(Jpd,1,Npd)
break
end
end
local Opd,Ppd,Qpd,Rpd
for Spd,Tpd in ipairs(Jpd)do
local Upd,Vpd=U.flat(Tpd.m:GetPivot().Position),Tpd.m._stats.range.Value
local Wpd,Xpd,Ypd=0,0,nil
for Zpd,_pd in ipairs(Ipd)do
if _pd~=Tpd and(U.flat(_pd.m:GetPivot().Position)-Upd).Magnitude<=Vpd then
Wpd,Xpd=Wpd+_pd.dps,Xpd+1
if not Ypd or _pd.dps>Ypd.dps then
Ypd=_pd
end
end
end
if Xpd>0 then
Opd,Ppd,Qpd,Rpd=Tpd,Wpd,Xpd,Ypd
break
end
end
Rpd=Rpd or Ipd[1]
local aqd=Rpd.dps*bb.airBoost(Rpd.m)*bb.reach(Rpd.m)*(Hpd==bb.planId and 2 or 1)
if(bb.mergeIds[Hpd]or Hpd==bb.planId)and(Opd or vpd[Hpd])and(not Gpd or aqd>Gpd.score)then
Gpd={id=Hpd,top=Rpd,fresh=Opd,near=Ppd or 0,n=Qpd or 0,coming=vpd[Hpd],score=aqd}
end
end
bb.planId,bb.freshM=Gpd and Gpd.id,Gpd and Gpd.fresh and Gpd.fresh.m
bb.mergeHeldAt=(kpd and Gpd and Gpd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not Gpd then
return F.status(Tse[4637],Tse[4723])
end
local bqd,cqd=bb.wave(),(bb.total or 30)-bb.wave()
local dqd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local eqd=Gpd.fresh
local fqd=not dqd and cqd>3
Gpd.waits=eqd and eqd.lvl<=Gpd.top.lvl and Gpd.top.lvl<Gpd.top.max and fqd or false
local gqd=(not eqd or eqd.lvl>=Gpd.top.lvl)and Gpd.coming and fqd
local hqd=bb.cloneCard and Gpd.top.lvl>=Gpd.top.max and fqd
local iqd=eqd and eqd.lvl>Gpd.top.lvl and Gpd.near<0.3*eqd.dps
Gpd.ready=kpd and eqd~=nil and not iqd and(not(Gpd.waits or gqd or hqd)or bqd-(bb.mergeHeldAt or bqd)>=5)
bb.holdNoCardAt=(Gpd.waits and not kpd)and(bb.holdNoCardAt or bqd)or nil
Gpd.hold=Gpd.waits and(kpd or bqd-(bb.holdNoCardAt or bqd)<4)
bb.mergePlan=Gpd
F.status(Tse[4637],eqd and string.format(Tse[4724],V.name(Gpd.id),Gpd.n,Gpd.n==1 and Tse[4725]or Tse[4726],eqd.lvl,Gpd.ready and Tse[4727]or(kpd and Tse[4728]or Tse[4729]))or string.format(Tse[4730],V.name(Gpd.id)))
end
function bb.mergeHold(jqd)
