end
end
for MCd,NCd in ipairs(FCd.placed or{})do
NCd.why=nil
end
GCd=U.json(FCd)
if#GCd<=3900 then
return GCd
end
if FCd.mapData then
FCd.mapData.dens=nil
end
GCd=U.json(FCd)
if#GCd<=3900 then
return GCd
end
FCd.placed,FCd.plan=nil,nil
