function nb.K.key(xZd,yZd)
local zZd,AZd,BZd=nb.K,nb.Win,Enum.KeyCode
if zZd.cur and not(zZd.cur.obj and zZd.cur.obj.Parent and zZd.shown(zZd.cur.obj))then
zZd.setFocus(nil)
end
if zZd.cur and zZd.cur.listKey and zZd.cur.listKey(xZd)then
