zZd.setFocus(nil)
AZd:SelectTab(CZd[HZd].name)
return true
end
if xZd==BZd.Tab or xZd==BZd.Down or xZd==BZd.Up then
local KZd=zZd.order()
if#KZd==0 then
return true
end
local LZd=xZd==BZd.Up or(xZd==BZd.Tab and yZd)
local MZd=table.find(KZd,zZd.cur)
if not MZd then
MZd=LZd and#KZd or 1
else
MZd=(MZd-1+(LZd and-1 or 1))% #KZd+1
end
zZd.setFocus(KZd[MZd])
return true
end
if not zZd.cur then
return false
end
if xZd==BZd.Return or xZd==BZd.KeypadEnter or xZd==BZd.Space then
if zZd.cur.activate then
zZd.cur.activate()
end
return true
end
if xZd==BZd.Left or xZd==BZd.Right then
if zZd.cur.adjust then
zZd.cur.adjust(xZd==BZd.Right and 1 or-1)
end
return true
end
if xZd==BZd.Escape then
zZd.setFocus(nil)
return true
end
return false
end
